"""Tiêu đề, suite, severity, review status và nội dung (tiền điều kiện, dữ liệu, bước, kết quả mong đợi) của 187 case trong R9_Test_Cases_final_FS09.xlsx. Tạo bởi tools/build_coverage.py, dùng cho reporting.py."""
from __future__ import annotations

CASES = {
    "TC-001": {'title': 'Parent signs in with Singpass and reaches the child list', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. The portal is open on the sign in page.\n2. Parent PAR-S10 (Parent of Ethan Chua, S8411530D) exists in the Singpass mock and is linked to S10 Ethan Chua and X03 Emma Chua.', 'test_data': 'Parent: PAR-S10\nLinked children: S10 Ethan Chua, X03 Emma Chua', 'steps': '1. Start the Singpass sign in.\n2. Sign in as PAR-S10 in the Singpass mock.\n3. Look at the screen that opens.', 'expected': '1. A session is created for PAR-S10.\n2. SCR-01 opens and lists the children linked to PAR-S10: S10 Ethan Chua and X03 Emma Chua (AC-01).'},
    "TC-002": {'title': 'Failed Singpass sign in creates no session', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. The portal is open on the sign in page.\n2. The Singpass mock is set to fail the sign in.', 'test_data': 'Parent: PAR-S10', 'steps': '1. Start the Singpass sign in.\n2. Let the Singpass mock fail the sign in.\n3. Try to open the SCR-01 address of the portal directly.', 'expected': '1. An error is shown after the failed sign in and no session is created.\n2. Opening the SCR-01 address shows the message "Your session has expired. Please sign in again." and moves to the Singpass sign in.\n3. No child data is shown.'},
    "TC-003": {'title': 'Cancelled Singpass sign in creates no session', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. The portal is open on the sign in page.', 'test_data': 'Parent: PAR-S10', 'steps': '1. Start the Singpass sign in.\n2. Cancel the sign in on the Singpass mock page.\n3. Return to the portal.', 'expected': '1. No session is created.\n2. The portal shows an error or the sign in page and no child data.\n3. The Parent can start the sign in again.'},
    "TC-004": {'title': 'Child list shows name, school, level, class and outstanding label', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in.\n2. Seed data is loaded: S10 Ethan Chua and X03 Emma Chua each have at least one Issued invoice.', 'test_data': 'Parent: PAR-S10', 'steps': '1. Open SCR-01.\n2. Read the entry of each child.', 'expected': '1. Each entry shows the student name, the school (Meridian Secondary), the level (also called cohort) and the class: Ethan Chua Sec 3, Sec 3 Excellence; Emma Chua Sec 3, Sec 3 Excellence.\n2. Each entry shows the label that the child has outstanding invoices.'},
    "TC-005": {'title': 'Label shows no outstanding invoices for a child without any', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S25 is signed in.\n2. X02 Sara Karim has no invoice at all. S25 Nadia Karim has the Issued invoices INV-2026-000126 and INV-2026-000127.\n3. S13 Amira Hassan (PAR-S13) has only the Paid invoice INV-2026-000119.', 'test_data': 'Parent: PAR-S25\nChildren: S25 Nadia Karim, X01 Hakim Karim, X02 Sara Karim\nSecond check: PAR-S13 with child S13 Amira Hassan', 'steps': '1. Open SCR-01 as PAR-S25.\n2. Compare the labels of X02 Sara Karim and S25 Nadia Karim.\n3. Sign out, sign in as PAR-S13 and read the label of S13 Amira Hassan.', 'expected': '1. X02 Sara Karim shows the label that there are no outstanding invoices.\n2. S25 Nadia Karim shows the label that there are outstanding invoices.\n3. S13 Amira Hassan shows the label that there are no outstanding invoices because her only invoice is Paid (AC-02).'},
    "TC-006": {'title': 'Child list contains only the children linked to the Parent', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in.\n2. Other students such as S01 Nur Aisyah, S02 Aisha Rahman and S25 Nadia Karim exist but are not linked to PAR-S10.', 'test_data': 'Parent: PAR-S10', 'steps': '1. Open SCR-01.\n2. Count the children and read their names.', 'expected': '1. Exactly two children are listed: S10 Ethan Chua and X03 Emma Chua.\n2. No other student appears and no invoice of another family is shown.'},
    "TC-007": {'title': 'Parent without any linked child sees the empty state', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-X02 Wong Kar Seng is signed in. PAR-X02 has no linked student (R8 seed).\n2. R8 AC-3 stops this Parent with MSG-0801 at sign in. If the sign in is stopped there, this case is Blocked until BA says whether the empty state of SCR-01 can be reached (see the Note).', 'test_data': 'Parent: PAR-X02 Wong Kar Seng (S8467890B)', 'steps': '1. Sign in as PAR-X02 and open SCR-01.', 'expected': '1. SCR-01 shows the empty state: no children are linked.\n2. The screen tells the Parent to contact the school.\n3. No student and no invoice is shown.'},
    "TC-008": {'title': 'Parent with one child reaches that child', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S04 is signed in. PAR-S04 has one linked child, S04 Ryan Lim.', 'test_data': 'Parent: PAR-S04\nStudent: S04', 'steps': '1. Sign in as PAR-S04.\n2. Look at the screen that opens.', 'expected': '1. Either SCR-01 lists only S04, or the system goes straight to SCR-02 of S04.\n2. No other student is shown.'},
    "TC-009": {'title': 'Second guardian linked to the same child sees the same child and invoices', 'suite': 'F9.1 Access and child list', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S25 and PAR-S25-F are both linked to S25 Nadia Karim (and to X01 Hakim Karim and X02 Sara Karim).\n2. Seed data is loaded.', 'test_data': 'Parents: PAR-S25 and PAR-S25-F\nStudent: S25 Nadia Karim\nInvoices of S25 seen by both Parents: INV-2026-000126 Issued 2.25 (Gross 27.25, FAS subsidy 25.00), INV-2026-000127 Issued 5.83 (Gross 70.63, FAS subsidy 64.80)', 'steps': '1. Sign in as PAR-S25, open S25 and note the invoice list.\n2. Sign out. Sign in as PAR-S25-F, open S25 and note the invoice list.', 'expected': '1. PAR-S25-F sees S25 on SCR-01.\n2. Both Parents see the same invoices with the same amounts and statuses: INV-2026-000126 (2.25) and INV-2026-000127 (5.83), both Issued.\n3. PAR-S25-F can select an Issued invoice and open SCR-04.'},
    "TC-010": {'title': 'System error while loading the child list shows a safe message', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05', 'preconditions': '1. PAR-S10 has a valid session.\n2. A Function 9 service is set to return an error for the child list.', 'test_data': 'Parent: PAR-S10', 'steps': '1. Open SCR-01 while the service returns an error.', 'expected': '1. SCR-01 shows the Error state with the message "Something went wrong. Please try again later."\n2. The Parent can try again.\n3. No data is changed and no technical detail is shown.'},
    "TC-011": {'title': 'Changing the student ID in the address is refused', 'suite': 'F9.1 Access and child list', 'page': 'SCR-02 Outstanding fees', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05', 'preconditions': '1. PAR-S01 is signed in and has opened SCR-02 of S01.\n2. S10 exists and is not linked to PAR-S01.', 'test_data': 'Parent: PAR-S01\nOwn child: S01\nOther family child: S10 Ethan Chua, Id f063b14b-8ec5-507d-84ad-9a9d36a79c26 (invoice INV-2026-000114)', 'steps': '1. Copy the address of SCR-02.\n2. Replace the student ID of S01 with the ID of S10.\n3. Open the changed address.', 'expected': '1. The server answers 403.\n2. The screen shows "You do not have access to this student\'s records." and returns to SCR-01.\n3. No invoice, amount or EA balance of S10 is shown.\n4. A security log entry is written.'},
    "TC-012": {'title': 'API call for the invoices of an unlinked student is refused', 'suite': 'F9.1 Access and child list', 'page': 'API: list invoices', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.', 'test_data': 'Parent: PAR-S01\nStudent: S10 Ethan Chua (Id f063b14b-8ec5-507d-84ad-9a9d36a79c26)', 'steps': '1. Send the list invoices request for S10 with the session of PAR-S01.\n2. Send the same request for S01.', 'expected': '1. The request for S10 returns 403 and no invoice data. A security log entry is written.\n2. The request for S01 returns the invoices of S01.'},
    "TC-013": {'title': 'API call to read an invoice of another family is refused', 'suite': 'F9.1 Access and child list', 'page': 'API: invoice detail', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-23: An invoice, transaction or receipt of a student who is not linked to the Parent is rejected like EX-01: 403, the FORBIDDEN_CHILD message in the screen, no data returned and a security log e', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.\n2. Invoice INV-2026-000114 belongs to S10.', 'test_data': 'Parent: PAR-S01\nInvoice: INV-2026-000114 (S10)', 'steps': '1. Send the invoice detail request for INV-2026-000114 with the session of PAR-S01.', 'expected': '1. The request is refused with 403 and returns no invoice data.\n2. The screen message is "You do not have access to this student\'s records."\n3. A security log entry is written.'},
    "TC-014": {'title': 'API call to pay an invoice of another family is refused and nothing is debited', 'suite': 'F9.1 Access and child list', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-23: An invoice, transaction or receipt of a student who is not linked to the Parent is rejected like EX-01: 403, the FORBIDDEN_CHILD message in the screen, no data returned and a security log e', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.\n2. Invoice INV-2026-000114 (22.23 SGD) is Issued and belongs to S10. S10 EA balance is 3,183.50.', 'test_data': 'Parent: PAR-S01\nInvoice: INV-2026-000114\nMethod: EA\nIdempotency key: SEC-KEY-001', 'steps': '1. Send the create payment request for INV-2026-000114 with method EA, using the session of PAR-S01.\n2. Look at the transactions of INV-2026-000114 and the EA balance of S10.', 'expected': '1. The request is refused with 403.\n2. No transaction exists for INV-2026-000114. Invoice INV-2026-000114 is still Issued.\n3. The EA balance of S10 is still 3,183.50.\n4. A security log entry is written.'},
    "TC-015": {'title': "API call for the status or receipt of another family's payment is refused", 'suite': 'F9.1 Access and child list', 'page': 'API: transaction status and receipt', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-23: An invoice, transaction or receipt of a student who is not linked to the Parent is rejected like EX-01: 403, the FORBIDDEN_CHILD message in the screen, no data returned and a security log e', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.\n2. The seed has the transaction PAY-20261008-000002 of S13 Amira Hassan (started by PAR-S13): EA 21.26 Succeeded, invoice INV-2026-000119 Paid, with a receipt.', 'test_data': 'Parent: PAR-S01\nTransaction: PAY-20261008-000002 (PAR-S13, R9-TXN-0002)\nTransaction PAY-20261008-000002: invoice INV-2026-000119 (21.26) Paid by the EA of S13, transaction Succeeded, S13 EA balance 558.74', 'steps': '1. Send the transaction status request for PAY-20261008-000002 with the session of PAR-S01.\n2. Send the receipt download request for PAY-20261008-000002 with the session of PAR-S01.', 'expected': '1. Both requests are refused with 403 and return no data.\n2. No receipt file is returned.\n3. A security log entry is written.\n4. PAY-20261008-000002 is still Succeeded, INV-2026-000119 is still Paid and the EA balance of S13 is still 558.74.'},
    "TC-016": {'title': 'A guardian cannot open a child who is linked only to another Parent', 'suite': 'F9.1 Access and child list', 'page': 'SCR-02 Outstanding fees', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S25-F is signed in. PAR-S25-F is linked to S25, X01 and X02 only.\n2. S10 Ethan Chua is linked to PAR-S10 only.', 'test_data': 'Parent: PAR-S25-F\nStudent: S10 Ethan Chua (Id f063b14b-8ec5-507d-84ad-9a9d36a79c26)', 'steps': '1. Open SCR-02 of S25.\n2. Change the student ID in the address to the ID of S10.', 'expected': '1. S25 opens normally.\n2. The changed address returns 403 and the message "You do not have access to this student\'s records."\n3. No data of S10 is shown.'},
    "TC-017": {'title': 'Request without a session is sent to the sign in', 'suite': 'F9.1 Access and child list', 'page': 'API: list invoices', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-06', 'preconditions': '1. No Parent is signed in.', 'test_data': 'Student: S01', 'steps': '1. Send the list invoices request for S01 without a session.\n2. Open the address of SCR-02 in a new browser with no session.', 'expected': '1. Both attempts return no data.\n2. The portal shows "Your session has expired. Please sign in again." and moves to the Singpass sign in.'},
    "TC-018": {'title': 'Open invoices of the chosen child are listed with number, due date, status and amount', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-03: SCR-02 lists invoices in Issued (payable) and PaymentPending (shown as Pending, not selectable). Paid, Cancelled and Draft are not listed. The total owed is the sum of Net of the listed inv', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in.\n2. Base seed data is loaded for S10 Ethan Chua: INV-2026-000113 (Issued, overdue, 36.33), INV-2026-000114 (Issued, 22.23), INV-2026-000115 (Issued, 19.66), INV-2026-000116 (Issued, 19.66).', 'test_data': 'Parent: PAR-S10\nStudent: S10 Ethan Chua\nAmounts are Net after the R4 FAS subsidy (@ApplyFasSubsidy = 1). With @ApplyFasSubsidy = 0 the amounts are 36.33, 47.23, 36.33 and 36.33.', 'steps': '1. On SCR-01 choose S10 Ethan Chua.\n2. Read the invoice list.', 'expected': '1. The list shows INV-2026-000113, INV-2026-000114, INV-2026-000115 and INV-2026-000116.\n2. Each invoice shows its number, due date, status and the amount to pay in SGD.\n3. INV-2026-000113 shows 36.33 (due 31/07/2026), INV-2026-000114 shows 22.23 (due 30/10/2026), INV-2026-000115 shows 19.66 (due 16/11/2026) and INV-2026-000116 shows 19.66 (due 15/12/2026).\n4. The total owed is 97.88.\n5. No invoice of X03 Emma Chua (INV-2026-000130) is shown.'},
    "TC-019": {'title': 'An invoice opens to its lines grouped by fee type with fee components and GST', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in and has opened SCR-02 of S10 Ethan Chua.', 'test_data': 'Invoice: INV-2026-000114 (Gross 47.23, FAS subsidy 25.00, Net 22.23)\nL1 Miscellaneous fee, Miscellaneous fee Term 4: base 33.33 + GST 3.00 = 36.33, subsidy 25.00, Net 11.33\nL2 Ad hoc, Service charge Term 4: base 10.00 + GST 0.90 = 10.90, subsidy 0.00, Net 10.90\nThe seed has no School fee and no Extracurricular line (R4 has no fee type).', 'steps': '1. Expand INV-2026-000114.\n2. Read each line and its components.', 'expected': '1. The two lines are shown grouped by fee type: miscellaneous fee and ad hoc.\n2. Each line shows its description, its fee components including GST, its subsidy and its amount.\n3. For each line the components add up to the line Gross: 36.33 and 10.90.'},
    "TC-020": {'title': 'Invoice totals show Gross, Subsidy 0.00 and Net equal to Gross', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in and has expanded INV-2026-000114 of S10 Ethan Chua.\n2. The seed was loaded with @ApplyFasSubsidy = 0 (BR-F9-08: Sprint 1 shows subsidy 0, open point O19).', 'test_data': 'Invoice: INV-2026-000114\nGross 47.23, Subsidy 0.00, Net 47.23\nLines: 36.33 + 10.90', 'steps': '1. Read the Gross, Subsidy and Net amounts of each line.\n2. Read the amount to pay of the invoice.\n3. Add the lines by hand.', 'expected': '1. Every line shows Subsidy 0.00 and Net equal to Gross.\n2. The invoice shows Subsidy 0.00 and an amount to pay of 47.23, equal to the sum of the line amounts 36.33 + 10.90.\n3. The Parent sees the Gross amount, not a reduced amount.'},
    "TC-021": {'title': 'Amounts are shown in SGD with two decimals', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S4 (lowest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Low', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S01 is signed in and has opened SCR-02 of S01 Nur Aisyah.', 'test_data': 'Invoice: INV-2026-000101 (27.25)\nEA balance: 1,590.00', 'steps': '1. Read the currency and the format of every amount on the screen, including the EA balance.', 'expected': '1. Every amount is in SGD and has two decimals, for example 27.25 and not 27.\n2. The EA balance is shown as 1,590.00 (thousands separator as in the seed, open point O12).'},
    "TC-022": {'title': 'Invoice due date is the earliest due date of its lines', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in and has opened SCR-02 of S10 Ethan Chua.\n2. INV-2026-000114 has two lines (Miscellaneous fee Term 4 and Service charge Term 4). The seed stores the due date on the invoice only (30/10/2026); the invoice_items table has no due date column.', 'test_data': 'Invoice: INV-2026-000114, due date 30/10/2026', 'steps': '1. Read the due date of INV-2026-000114.', 'expected': '1. INV-2026-000114 shows the due date 30/10/2026, the earliest due date of its lines.'},
    "TC-023": {'title': 'Switching to another child changes the invoice list', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in and has opened SCR-02 of S10 Ethan Chua.', 'test_data': 'Parent: PAR-S10\nStudents: S10 Ethan Chua, X03 Emma Chua', 'steps': '1. Use the change child action and choose X03 Emma Chua.\n2. Read the invoice list.\n3. Go back and choose S10 Ethan Chua again.', 'expected': '1. For X03 only INV-2026-000130 (36.33) is shown and no invoice of S10.\n2. For S10 the four invoices of S10 are shown again.'},
    "TC-024": {'title': 'Paid, Cancelled and Draft invoices are not in the list', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-03: SCR-02 lists invoices in Issued (payable) and PaymentPending (shown as Pending, not selectable). Paid, Cancelled and Draft are not listed. The total owed is the sum of Net of the listed inv', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S16 and PAR-S07 are used (sign in as each).\n2. S16 Darren Ho has INV-2026-000121 (Paid) and INV-2026-000122 (Issued). S07 Priya Nair has INV-2026-000110 (Cancelled) and INV-2026-000109 (Issued).\n3. The seed has no Draft invoice: helper H-DRAFT creates INV-2026-000199 (Draft) for S16.', 'test_data': 'Students: S16 Darren Ho (PAR-S16), S07 Priya Nair (PAR-S07)\nInvoices not expected: INV-2026-000121 (Paid), INV-2026-000110 (Cancelled), INV-2026-000199 (Draft, helper)\nInvoices expected: INV-2026-000122 (S16, 6.63) and INV-2026-000109 (S07, 21.26)', 'steps': '1. Sign in as PAR-S16 and open SCR-02 of S16. Look for INV-2026-000121 and INV-2026-000199.\n2. Sign in as PAR-S07 and open SCR-02 of S07. Look for INV-2026-000110.', 'expected': '1. INV-2026-000121 (Paid) and INV-2026-000199 (Draft) are not in the list of S16. Only INV-2026-000122 (6.63) is listed.\n2. The Draft invoice is never shown to the Parent.\n3. INV-2026-000110 (Cancelled) is not in the list of S07. Only INV-2026-000109 (21.26) is listed.'},
    "TC-025": {'title': 'An invoice waiting for payment is shown as Pending and cannot be selected', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-03: SCR-02 lists invoices in Issued (payable) and PaymentPending (shown as Pending, not selectable). Paid, Cancelled and Draft are not listed. The total owed is the sum of Net of the listed inv', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S08 is signed in.\n2. INV-2026-000111 of S08 Farhan Ismail is PaymentPending with an open transaction (seed).', 'test_data': 'Invoice: INV-2026-000111 (27.25)\nOpen transaction: PAY-20261020-000004 (R9-TXN-0004), Pending, online leg 27.25 Pending (FND-20261020-000004-1)', 'steps': '1. Open SCR-02 of S08.\n2. Look at INV-2026-000111.\n3. Try to select INV-2026-000111.', 'expected': '1. INV-2026-000111 shows the status Pending.\n2. INV-2026-000111 cannot be selected for payment.\n3. SCR-04 does not open for INV-2026-000111.\n4. INV-2026-000111 is still PaymentPending and no second transaction is created. PAY-20261020-000004 stays Pending.'},
    "TC-027": {'title': 'Demo data is labelled as sample data', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-26: A label that says the data is sample data is visible on SCR-02 where the invoices and the EA balance are shown. A portal wide banner also passes.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S01 is signed in and has opened SCR-02 of S01.', 'test_data': 'Student: S01', 'steps': '1. Look for a label that says the data is sample data.', 'expected': '1. A label shows clearly that the invoices and the EA balance are sample data.\n2. The page does not present the data as real billing.'},
    "TC-028": {'title': 'A child with an Active EA shows balance and status', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S01 is signed in.', 'test_data': 'Student: S01, EA Active, balance 1,590.00', 'steps': '1. Open SCR-02 of S01.\n2. Read the EA widget.', 'expected': '1. The widget shows the EA balance 1,590.00 SGD and the EA status Active.'},
    "TC-029": {'title': 'A child without an EA shows no balance and a note', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S07 is signed in.\n2. S07 Priya Nair is a Permanent Resident and has no EA.', 'test_data': 'Student: S07', 'steps': '1. Open SCR-02 of S07.\n2. Look for the EA widget.', 'expected': '1. No EA balance is shown.\n2. A note says that the student has no Education Account.'},
    "TC-030": {'title': 'A child with a Closed EA shows the status Closed', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-X01 is signed in.\n2. X05 has an EA with the status Closed and balance 0.00.', 'test_data': 'Student: X05', 'steps': '1. Open SCR-02 of X05.\n2. Read the EA widget.', 'expected': '1. The EA status is shown as Closed.\n2. The widget does not offer the EA as a way to pay.'},
    "TC-031": {'title': 'A zero EA balance is shown as 0.00', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S4 (lowest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Low', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in.\n2. S02 has an Active EA with balance 0.00 (helper H-EA sets it, seed value 20.00).', 'test_data': 'Student: S02 Aisha Rahman, EA balance 0.00 (helper H-EA)', 'steps': '1. Open SCR-02 of S02.\n2. Read the EA widget.', 'expected': '1. The balance is shown as 0.00 SGD and the status as Active.'},
    "TC-032": {'title': 'A child with no Issued invoice shows the empty state', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-03 No outstanding fees', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-03: SCR-02 lists invoices in Issued (payable) and PaymentPending (shown as Pending, not selectable). Paid, Cancelled and Draft are not listed. The total owed is the sum of Net of the listed inv', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S13 is signed in.\n2. S13 Amira Hassan has only INV-2026-000119 (Paid). Her charge CH17 is in that Paid invoice.', 'test_data': 'Student: S13 Amira Hassan', 'steps': '1. On SCR-01 choose S13 Amira Hassan.', 'expected': '1. SCR-03 opens with a message that there are no outstanding fees.\n2. A link back to SCR-01 is shown.\n3. No payment option is shown.'},
    "TC-033": {'title': 'The empty state links back to the child list and another child can be chosen', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-03 No outstanding fees', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S25 is signed in and is on SCR-03 of X02 Sara Karim (no invoice).', 'test_data': 'Students: X02 Sara Karim, S25 Nadia Karim', 'steps': '1. Use the link back on SCR-03.\n2. Choose S25 Nadia Karim.', 'expected': '1. SCR-01 opens with the children of PAR-S25.\n2. SCR-02 of S25 opens with its invoices INV-2026-000126 and INV-2026-000127.'},
    "TC-034": {'title': 'A child whose only open invoice is waiting for payment is not shown the empty state', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-03: SCR-02 lists invoices in Issued (payable) and PaymentPending (shown as Pending, not selectable). Paid, Cancelled and Draft are not listed. The total owed is the sum of Net of the listed inv', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05', 'preconditions': '1. PAR-S05 is signed in.\n2. The only open invoice of S05 Chen Xin Yi, INV-2026-000106, is PaymentPending with an open transaction (seed). The transaction PAY-20261021-000005 is ReconciliationRequired (EA 27.25, the result of the debit is not known).', 'test_data': 'Student: S05 Chen Xin Yi\nInvoice: INV-2026-000106 (PaymentPending, 27.25)', 'steps': '1. On SCR-01 choose S05 Chen Xin Yi.', 'expected': '1. SCR-02 opens and shows INV-2026-000106 with the status Pending.\n2. SCR-03 is not shown.\n3. INV-2026-000106 is still PaymentPending and no second transaction is created for it.'},
    "TC-035": {'title': 'Selecting an Issued invoice opens the payment method screen with its summary', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and has opened SCR-02 of S02.\n2. INV-2026-000103 (70.63) is Issued.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Select INV-2026-000103.', 'expected': '1. SCR-04 opens.\n2. It shows a summary of the invoice: the child, the invoice number and the amount to pay 70.63 SGD.\n3. It shows three options: EA (with the balance 20.00, disabled because 20.00 is below 70.63), online payment, and split (EA plus online) proposed with the EA part 20.00 and the online part 50.63.\n4. Opening SCR-04 creates nothing: no new transaction exists, INV-2026-000103 is still Issued and the EA balance is still 20.00.'},
    "TC-036": {'title': 'Only one whole invoice can be selected and lines cannot be paid separately', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in and has opened SCR-02 of S10 Ethan Chua.\n2. INV-2026-000114 and INV-2026-000115 are Issued.', 'test_data': 'Invoices: INV-2026-000114 (two lines, 22.23), INV-2026-000115 (one line, 19.66)', 'steps': '1. Look for a way to select two invoices at once.\n2. Look for a way to pay one line of INV-2026-000114.\n3. Select INV-2026-000114.', 'expected': '1. No control selects two invoices in one payment.\n2. No control pays a single line or a part of an invoice.\n3. SCR-04 opens for the whole INV-2026-000114 with the amount 22.23.\n4. Opening SCR-04 creates no transaction and INV-2026-000114 is still Issued.'},
    "TC-038": {'title': 'Student without an EA can pay online only', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-13: For a student without EA, the EA and split options are disabled and the EA_NOT_AVAILABLE text is shown as guidance, not as an error banner or error state.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S07 is signed in.\n2. S07 has no EA.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (21.26)', 'steps': '1. Select INV-2026-000109 on SCR-02 of S07.\n2. Read the options and any text on SCR-04.', 'expected': '1. The EA option and the split option are disabled.\n2. The online payment option is available.\n3. The text "This student does not have an Education Account. Please pay online." is shown as guidance and no error state or error banner is shown.\n4. The Parent can continue with the online payment.\n5. Nothing is created: no transaction exists and INV-2026-000109 is still Issued.'},
    "TC-039": {'title': 'Student with a Closed EA can pay online only', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-X01 is signed in.\n2. X05 has an EA with the status Closed.', 'test_data': 'Student: X05 Lim Wei Jie (Riverside Secondary, Sec 5, class Sec 5 Resilience), Singapore Citizen, EA status Closed, balance 0.00 SGD\nInvoice: INV-2026-000131 (27.25)', 'steps': '1. Select INV-2026-000131 on SCR-02 of X05.\n2. Read the options and any text on SCR-04.', 'expected': '1. The EA option and the split option are disabled.\n2. The online payment option is available.\n3. The text "The Education Account is not active. Please pay online." is shown.\n4. Nothing is created: no transaction exists, INV-2026-000131 is still Issued and the EA balance is still 0.00.'},
    "TC-040": {'title': 'Active EA with zero balance offers online payment only', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in.\n2. S02 has an Active EA with balance 0.00 (helper H-EA sets it, seed value 20.00).', 'test_data': 'Student: S02 Aisha Rahman, EA balance 0.00 (helper H-EA) Aisha Rahman, Singapore Citizen, EA Active, balance 0.00 SGD\nInvoice: INV-2026-000102 (21.26)', 'steps': '1. Select INV-2026-000102 on SCR-02 of S02.\n2. Read the options and any text on SCR-04.', 'expected': '1. The EA option is disabled.\n2. The split option is disabled because split needs a balance above 0.\n3. The online payment option is available.\n4. The text "Your Education Account balance is not enough for this amount. You can pay the rest online." is shown.\n5. Nothing is created: no transaction exists, INV-2026-000102 is still Issued and the EA balance is still 0.00.'},
    "TC-041": {'title': 'Balance below the amount to pay disables EA and suggests split', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in.\n2. S02 EA is Active with balance 20.00.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Select INV-2026-000103 on SCR-02 of S02.\n2. Read the options on SCR-04.', 'expected': '1. The EA only option is disabled.\n2. The split option is offered with the EA part 20.00 and the online part 50.63.\n3. The online payment option is available.\n4. The text "Your Education Account balance is not enough for this amount. You can pay the rest online." is shown with the suggestion to pay the rest online.\n5. Nothing is created: no new transaction exists, INV-2026-000103 is still Issued and the EA balance is still 20.00.'},
    "TC-042": {'title': 'Balance equal to the amount to pay allows EA and online but not split', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-02: When the available balance is equal to or higher than the payable amount, the split option is not offered.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S04 is signed in.\n2. S04 EA is Active with balance 21.26 (helper H-EA sets it, seed value 975.00).', 'test_data': 'Student: S04 Ryan Lim (Bukit View Primary, P5, class P5 Honesty), Singapore Citizen, EA Active, balance 21.26 SGD (helper H-EA sets the balance of S04 to 21.26, seed value 975.00)\nInvoice: INV-2026-000105 (21.26)', 'steps': '1. Select INV-2026-000105 on SCR-02 of S04.\n2. Read the options on SCR-04.', 'expected': '1. The EA option is enabled.\n2. The online payment option is enabled.\n3. The split option is not offered.\n4. Nothing is created: no transaction exists, INV-2026-000105 is still Issued and the EA balance is still 21.26.'},
    "TC-043": {'title': 'Balance above the amount to pay allows EA and online but not split', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-02: When the available balance is equal to or higher than the payable amount, the split option is not offered.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S01 is signed in.\n2. S01 EA is Active with balance 1,590.00.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (27.25)', 'steps': '1. Select INV-2026-000101 on SCR-02 of S01.\n2. Read the options on SCR-04.', 'expected': '1. The EA option is enabled and the balance 1,590.00 is shown.\n2. The online payment option is enabled.\n3. The split option is not offered.\n4. Nothing is created: no transaction exists, INV-2026-000101 is still Issued and the EA balance is still 1,590.00.'},
    "TC-045": {'title': 'The EA is suggested when the balance is enough but nothing is debited until the Parent confirms', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05', 'preconditions': '1. PAR-S01 is signed in.\n2. S01 EA is Active with balance 1,590.00.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (27.25)', 'steps': '1. Select INV-2026-000101 on SCR-02.\n2. Read SCR-04 without choosing a method.\n3. Look at the EA balance and the transactions of INV-2026-000101.\n4. Use the back action.', 'expected': '1. The EA may be suggested as the method.\n2. No method is applied until the Parent chooses it and confirms on SCR-05.\n3. The EA balance is still 1,590.00 and no transaction exists.'},
    "TC-046": {'title': 'Selecting EA with a low balance is refused with the reason and nothing changes', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 for INV-2026-000103 of S02.\n2. S02 EA balance is 20.00.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Try to choose the EA only option.\n2. Look at the screen, the transactions of INV-2026-000103 and the EA balance.', 'expected': '1. The EA only option cannot be chosen.\n2. The reason "Your Education Account balance is not enough for this amount. You can pay the rest online." is shown with the advice to pay online or to split.\n3. No transaction is created. INV-2026-000103 is still Issued. The EA balance is still 20.00.'},
    "TC-047": {'title': 'API refuses the EA method when the balance is too low', 'suite': 'F9.3 Payment method and eligibility', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S02 has a valid session.\n2. S02 EA balance is 20.00.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nMethod: EA\nIdempotency key: SEL-KEY-001\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Send the create payment request with method EA for INV-2026-000103.\n2. Look at the answer, the transactions of INV-2026-000103 and the EA balance.', 'expected': '1. The request is refused with the reason EA_INSUFFICIENT_BALANCE.\n2. No transaction is created. INV-2026-000103 is still Issued. The EA balance is still 20.00.'},
    "TC-048": {'title': 'API refuses EA and split for a student without an EA', 'suite': 'F9.3 Payment method and eligibility', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S07 has a valid session.\n2. S07 has no EA.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (21.26)\nMethods tried: EA, then SPLIT with EA 10.00 and online 11.26\nIdempotency keys: API-KEY-048A (EA), API-KEY-048B (SPLIT)', 'steps': '1. Send the create payment request with method EA for INV-2026-000109.\n2. Send the create payment request with method SPLIT (EA 10.00, online 11.26) for INV-2026-000109.\n3. Look at the transactions of INV-2026-000109.', 'expected': '1. Both requests are refused with the reason EA_NOT_AVAILABLE.\n2. No transaction is created and INV-2026-000109 is still Issued.'},
    "TC-049": {'title': 'API refuses EA and split when the EA is Closed', 'suite': 'F9.3 Payment method and eligibility', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-X01 has a valid session.\n2. X05 EA status is Closed.', 'test_data': 'Student: X05 Lim Wei Jie (Riverside Secondary, Sec 5, class Sec 5 Resilience), Singapore Citizen, EA status Closed, balance 0.00 SGD\nInvoice: INV-2026-000131 (27.25)\nMethods tried: EA, then SPLIT with EA 10.00 and online 17.25\nIdempotency keys: API-KEY-049A (EA), API-KEY-049B (SPLIT)', 'steps': '1. Send the create payment request with method EA for INV-2026-000131.\n2. Send the create payment request with method SPLIT (EA 10.00, online 17.25) for INV-2026-000131.\n3. Look at the transactions of INV-2026-000131.', 'expected': '1. Both requests are refused with the reason EA_NOT_ACTIVE.\n2. No transaction is created and INV-2026-000131 is still Issued.'},
    "TC-050": {'title': 'Default split proposes the whole balance as the EA part and calculates the online part', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 for INV-2026-000103 of S02.\n2. S02 EA balance is 20.00.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Choose the split option.\n2. Read the two amounts.', 'expected': '1. The EA part is 20.00, the whole available balance.\n2. The online part is 50.63, calculated by the system, and the Parent does not type it.\n3. The EA only option is disabled.\n4. Nothing is debited yet: no new transaction exists, INV-2026-000103 is still Issued and the EA balance is still 20.00.'},
    "TC-051": {'title': 'The Parent can lower the EA part and the online part updates', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-01: The EA part starts at the whole available balance. The Parent can lower it to any amount above 0 and below the payable amount, and the online part is then Net minus the EA part. AC-22 is fo', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 for INV-2026-000103 of S02, with the split option chosen.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nEA part changed from 20.00 to 10.00\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Change the EA part from 20.00 to 10.00.\n2. Read the online part.', 'expected': '1. The online part updates to 60.63.\n2. The two parts add up to 70.63.\n3. The Parent can continue to SCR-05.'},
    "TC-052": {'title': 'The online part cannot be typed by the Parent', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 for INV-2026-000103 of S02, with the split option chosen.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Try to type a value in the online amount.', 'expected': '1. The online amount is calculated and read only.\n2. Typing is not possible.'},
    "TC-053": {'title': 'An EA part of zero is refused and the Parent stays on the screen', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-01: The EA part starts at the whole available balance. The Parent can lower it to any amount above 0 and below the payable amount, and the online part is then Net minus the EA part. AC-22 is fo', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 for INV-2026-000103 of S02, with the split option chosen.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nEA part: 0.00\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Change the EA part to 0.00.\n2. Try to continue.', 'expected': '1. The message "The two amounts must be more than zero and add up to the total." is shown.\n2. The Parent stays on SCR-04 and the amount field is marked.\n3. No transaction is created, INV-2026-000103 is still Issued and the EA balance is still 20.00.'},
    "TC-054": {'title': 'API refuses a split with an online part of zero', 'suite': 'F9.3 Payment method and eligibility', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.\n2. S01 EA balance is 1,590.00.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (27.25)\nMethod: SPLIT, EA 27.25, online 0.00\nIdempotency key: API-KEY-054', 'steps': '1. Send the create payment request with the split amounts EA 27.25 and online 0.00.\n2. Look at the answer and the transactions of INV-2026-000101.', 'expected': '1. The request is refused with SPLIT_AMOUNT_INVALID.\n2. No transaction is created. INV-2026-000101 is still Issued. The EA balance is still 1,590.00.'},
    "TC-055": {'title': 'API refuses a split whose parts add up to less than the amount to pay', 'suite': 'F9.3 Payment method and eligibility', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S02 has a valid session.\n2. S02 EA balance is 20.00.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nMethod: SPLIT, EA 20.00, online 20.00 (sum 40.00)\nIdempotency key: API-KEY-055\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Send the create payment request with the split amounts EA 20.00 and online 20.00.\n2. Look at the answer and the transactions of INV-2026-000103.', 'expected': '1. The request is refused with SPLIT_AMOUNT_INVALID.\n2. No transaction is created, INV-2026-000103 is still Issued and the EA balance is still 20.00.'},
    "TC-056": {'title': 'API refuses a split whose parts add up to more than the amount to pay', 'suite': 'F9.3 Payment method and eligibility', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S02 has a valid session.\n2. S02 EA balance is 20.00.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nMethod: SPLIT, EA 20.00, online 55.00 (sum 75.00)\nIdempotency key: API-KEY-056\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Send the create payment request with the split amounts EA 20.00 and online 55.00.\n2. Look at the answer and the transactions of INV-2026-000103.', 'expected': '1. The request is refused with SPLIT_AMOUNT_INVALID.\n2. No transaction is created, INV-2026-000103 is still Issued and the EA balance is still 20.00.'},
    "TC-057": {'title': 'API refuses an EA part above the available balance', 'suite': 'F9.3 Payment method and eligibility', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S02 has a valid session.\n2. S02 EA balance is 20.00.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nMethod: SPLIT, EA 25.00, online 45.63\nIdempotency key: API-KEY-057\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Send the create payment request with the split amounts EA 25.00 and online 45.63.\n2. Look at the answer, the transactions and the EA balance.', 'expected': '1. The request is refused with the reason EA_INSUFFICIENT_BALANCE.\n2. No transaction is created, INV-2026-000103 is still Issued and the EA balance is still 20.00.'},
    "TC-058": {'title': 'API refuses a negative EA part', 'suite': 'F9.3 Payment method and eligibility', 'page': 'API: create payment', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-24: An amount that is not a number, is empty, is negative or has more than two decimals is rejected on SCR-04 with the field marked, no transaction is created and nothing changes. Zero or a neg', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S02 has a valid session.\n2. S02 EA balance is 20.00.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nMethod: SPLIT, EA -5.00, online 75.63\nIdempotency key: API-KEY-058\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Send the create payment request with the split amounts EA -5.00 and online 75.63.\n2. Look at the answer and the EA balance.', 'expected': '1. The request is refused. The message "The two amounts must be more than zero and add up to the total." is shown.\n2. No transaction is created, INV-2026-000103 is still Issued and the EA balance is still 20.00.'},
    "TC-062": {'title': 'A very small EA part is accepted because the EA part has no minimum', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S4 (lowest)', 'review': 'Draft', 'assumption': 'ASM-R9-01: The EA part starts at the whole available balance. The Parent can lower it to any amount above 0 and below the payable amount, and the online part is then Net minus the EA part. AC-22 is fo', 'priority': 'Low', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 for INV-2026-000103 of S02, with the split option chosen.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nEA part changed to 0.01, online part 70.62\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Change the EA part to 0.01.\n2. Read the online part.\n3. Continue to SCR-05.', 'expected': '1. The online part is 70.62.\n2. SCR-05 opens with the EA part 0.01 and the online part 70.62.\n3. Nothing is debited yet: no new transaction exists, INV-2026-000103 is still Issued and the EA balance is still 20.00.'},
    "TC-063": {'title': 'Review screen for an EA payment shows the amounts and the balance after payment', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-05 Review and confirm', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S01 is signed in and is on SCR-04 for INV-2026-000101 (27.25) of S01 Nur Aisyah.\n2. S01 EA balance is 1,590.00.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset\nMethod: EA', 'steps': '1. Choose the EA option and continue.\n2. Read SCR-05.', 'expected': '1. SCR-05 shows the child S01 Nur Aisyah, the invoice number and the amount to pay 27.25 SGD.\n2. It shows the method EA and the EA amount 27.25.\n3. It shows the EA balance after payment 1,562.75 as information only.\n4. No online part is shown.\n5. Nothing is debited on SCR-05: no transaction exists and the EA balance is still 1,590.00.'},
    "TC-065": {'title': 'Paying a 27.25 invoice with the EA debits the balance once and marks the invoice Paid', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-07 Payment confirmation', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S01 is signed in and is on SCR-05 for INV-2026-000101 (27.25) of S01 Nur Aisyah with the EA method.\n2. S01 EA balance is 1,590.00. S04 Ryan Lim EA balance is 975.00.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset\nMethod: EA\nIdempotency key: client generated', 'steps': '1. Confirm the payment.\n2. Read SCR-07.\n3. Look at the transaction, the EA leg, the invoice and the Function 1 ledger by the FundingReference.\n4. Read the EA balance of S01 and of S04 Ryan Lim.', 'expected': '1. SCR-07 shows success, a transaction reference, the time, the EA part 27.25 and the total 27.25.\n2. The transaction is Succeeded and the EA leg is Succeeded. Requested and Settled amounts are 27.25.\n3. The invoice is Paid.\n4. The ledger has one debit of 27.25 for the FundingReference and its ledger ID is stored in the EA leg.\n5. The EA balance of S01 is 1,562.75. The balance of S04 Ryan Lim is still 975.00.'},
    "TC-066": {'title': 'Status changes of an EA payment follow Appendix A and are written to the audit log', 'suite': 'F9.4 Pay with Education Account', 'page': 'Audit log', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05', 'preconditions': '1. INV-2026-000101 (27.25) of S01 Nur Aisyah is paid with the EA by PAR-S01.\n2. S01 EA is Active with balance 1,590.00. PAR-S01 is signed in and the invoice is Issued before the payment.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset', 'steps': '1. Pay the invoice with the EA.\n2. Read the audit log entries of the transaction, the EA leg and the invoice in time order.', 'expected': '1. The entries show: transaction created Pending and invoice Issued to PaymentPending; EA leg Pending to Succeeded; transaction Pending to Succeeded; invoice PaymentPending to Paid.\n2. Each entry has the actor, the action, the entity, the old and new value and a time.\n3. The EA balance falls once by 27.25 to 1,562.75.'},
    "TC-067": {'title': 'Paying a two line invoice of 22.23 (Gross 47.23 less the FAS subsidy 25.00) debits the full Net amount', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-07 Payment confirmation', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S10 is signed in and is on SCR-05 for INV-2026-000114 of S10 Ethan Chua with the EA method.\n2. S10 EA balance is 3,183.50.', 'test_data': 'Student: S10 Ethan Chua (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 3,183.50 SGD\nInvoice: INV-2026-000114, two lines, Gross 47.23, FAS subsidy 25.00, Net 22.23 (@ApplyFasSubsidy = 1)\nMethod: EA', 'steps': '1. Confirm the payment.\n2. Read SCR-07 and the EA balance.\n3. Look at the Requested amount of the transaction and of the EA leg.', 'expected': '1. The EA is debited 22.23 once and the balance is 3,161.27.\n2. The Requested amount of the transaction and of the EA leg is 22.23, equal to the Net amount of the invoice (not the Gross 47.23).\n3. The invoice is Paid.\n4. The transaction and the EA leg are Succeeded, the ledger has one debit of 22.23 and SCR-07 shows a transaction reference.'},
    "TC-068": {'title': 'Balance equal to the amount to pay is paid and the balance becomes 0.00', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-07 Payment confirmation', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S04 is signed in and is on SCR-05 for INV-2026-000105 of S04 with the EA method.\n2. S04 EA balance is 21.26 (helper H-EA sets it, seed value 975.00).', 'test_data': 'Student: S04 Ryan Lim (Bukit View Primary, P5, class P5 Honesty), Singapore Citizen, EA Active, balance 21.26 SGD (helper H-EA sets the balance of S04 to 21.26, seed value 975.00)\nInvoice: INV-2026-000105 (21.26)\nMethod: EA', 'steps': '1. Confirm the payment.\n2. Read SCR-07 and the EA balance.', 'expected': '1. The payment succeeds and the invoice is Paid.\n2. The EA balance is 0.00 and is never negative.\n3. The transaction and the EA leg are Succeeded, the ledger has one debit of 21.26 and SCR-07 shows a transaction reference.'},
    "TC-070": {'title': 'After an EA payment the list shows the new balance and no longer shows the invoice', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-03: SCR-02 lists invoices in Issued (payable) and PaymentPending (shown as Pending, not selectable). Paid, Cancelled and Draft are not listed. The total owed is the sum of Net of the listed inv', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 has just paid INV-2026-000114 of S10 Ethan Chua with the EA.', 'test_data': 'Student: S10 Ethan Chua (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 3,183.50 SGD\nInvoice: INV-2026-000114 (Net 22.23)', 'steps': '1. On SCR-07 go back to SCR-02 of S10.\n2. Read the EA widget and the invoice list.', 'expected': '1. The EA balance is 3,161.27.\n2. INV-2026-000114 is Paid, its transaction is Succeeded, and it is not in the list of outstanding invoices.\n3. The other invoices of S10 (INV-2026-000113, INV-2026-000115, INV-2026-000116) are unchanged.'},
    "TC-071": {'title': 'Balance falling below the amount before confirm fails the EA leg and changes nothing', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-08 Payment failed', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S01 is signed in and is on SCR-05 for INV-2026-000101 (27.25) of S01 Nur Aisyah with the EA method.\n2. S01 EA balance is 1,590.00 when SCR-05 opens.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset\nBalance changed to 10.00 before the confirm', 'steps': '1. Without leaving SCR-05, set the EA balance of S01 to 10.00 in Function 1.\n2. Confirm the payment.\n3. Look at the screen, the transaction, the EA leg, the invoice and the balance.', 'expected': '1. The EA leg is Failed and the transaction is Failed.\n2. The invoice is back to Issued.\n3. The EA balance is still 10.00 and no debit is in the ledger.\n4. The message "Your Education Account balance is not enough for this amount. You can pay the rest online." is shown with the advice to choose another method or to split.'},
    "TC-072": {'title': 'Function 1 error during the debit fails the payment and the invoice is not Paid', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-08 Payment failed', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S09 is signed in and is on SCR-05 for INV-2026-000112 (27.25) of S09 Jun Hao Wong with the EA method.\n2. Function 1 is set to fail the debit and roll it back.', 'test_data': 'Student: S09 Jun Hao Wong (Riverside Secondary, Sec 1, class Sec 1 Wisdom), Singapore Citizen, EA Active, balance 1,180.00 SGD\nInvoice: INV-2026-000112 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset', 'steps': '1. Confirm the payment.\n2. Look at SCR-08, the transaction, the EA leg, the invoice and the balance.', 'expected': '1. The EA leg is Failed, the transaction is Failed and the invoice is back to Issued.\n2. The EA balance is still 1,180.00 and no debit is in the ledger.\n3. SCR-08 shows "Your payment could not be completed. No amount was deducted." with the buttons Try again and Exit.'},
    "TC-073": {'title': 'Unclear debit result with Function 1 confirming nothing was debited fails the leg', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-08 Payment failed', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S09 is signed in and is on SCR-05 for INV-2026-000112 (27.25) of S09 Jun Hao Wong with the EA method.\n2. Function 1 times out on the debit and, when asked with the same FundingReference, answers that nothing was debited.', 'test_data': 'Student: S09 Jun Hao Wong (Riverside Secondary, Sec 1, class Sec 1 Wisdom), Singapore Citizen, EA Active, balance 1,180.00 SGD\nInvoice: INV-2026-000112 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset', 'steps': '1. Confirm the payment.\n2. Look at the calls to Function 1 and at the leg, the transaction, the invoice and the balance.', 'expected': '1. The system asks Function 1 again with the same FundingReference.\n2. The EA leg is Failed, the transaction is Failed and the invoice is Issued.\n3. The balance is still 1,180.00. The Parent sees "Your payment could not be completed. No amount was deducted."'},
    "TC-074": {'title': 'Unclear debit result with Function 1 confirming the debit leads to a reversal', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-08 Payment failed', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-16: If Function 1 confirms the debit after an unclear result, the system reverses it as BR-F9-03 says: the EA leg ends Reversed, the transaction Failed, the invoice Issued, the balance unchange', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S09 is signed in and is on SCR-05 for INV-2026-000112 (27.25) of S09 Jun Hao Wong with the EA method.\n2. Function 1 debits 27.25, then times out before it answers. When asked with the same FundingReference it answers that the debit was made.', 'test_data': 'Student: S09 Jun Hao Wong (Riverside Secondary, Sec 1, class Sec 1 Wisdom), Singapore Citizen, EA Active, balance 1,180.00 SGD\nInvoice: INV-2026-000112 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset', 'steps': '1. Confirm the payment.\n2. Look at the ledger, the EA leg, the transaction, the invoice and the balance.', 'expected': '1. The ledger shows exactly one debit and one reversal of 27.25 for the payment.\n2. The EA leg is Reversed, the transaction is Failed and the invoice is Issued.\n3. The EA balance is back to 1,180.00. The Parent sees "Your payment could not be completed. No amount was deducted."'},
    "TC-075": {'title': 'Unclear debit result that stays unclear moves to ReconciliationRequired', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-06 Pending', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S09 is signed in and is on SCR-05 for INV-2026-000112 (27.25) of S09 Jun Hao Wong with the EA method.\n2. Function 1 times out on the debit and also on every question about the FundingReference.', 'test_data': 'Student: S09 Jun Hao Wong (Riverside Secondary, Sec 1, class Sec 1 Wisdom), Singapore Citizen, EA Active, balance 1,180.00 SGD\nInvoice: INV-2026-000112 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset', 'steps': '1. Confirm the payment.\n2. Read the screen that opens.\n3. Look at the leg, the transaction, the invoice and the operations alerts.', 'expected': '1. The EA leg and the transaction are ReconciliationRequired.\n2. The invoice stays PaymentPending and is not Paid.\n3. SCR-06 shows the verifying state.\n4. An operations alert is raised.\n5. The system does not guess that the money was or was not debited, and it does not debit again.'},
    "TC-076": {'title': 'Function 1 treats the same FundingReference as one debit', 'suite': 'F9.4 Pay with Education Account', 'page': 'Function 1 debit API', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-15: Function 1 debits and reverses once per FundingReference. Function 9 may send the same FundingReference again after an error.', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-03', 'preconditions': '1. A FundingReference FR-TEST-01 for S09 and 27.25 is prepared.\n2. S09 EA balance is 1,180.00.', 'test_data': 'Student: S09\nFundingReference: FR-TEST-01\nAmount: 27.25', 'steps': '1. Send the debit call for FR-TEST-01 to Function 1.\n2. Send the same debit call again with the same FundingReference.\n3. Read the ledger and the balance.', 'expected': '1. The second call returns the result of the first call.\n2. The ledger has one debit for FR-TEST-01.\n3. The EA balance is 1,152.75.'},
    "TC-077": {'title': 'Double click on Confirm creates one transaction and debits once', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'SCR-05 Review and confirm', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S04 is signed in and is on SCR-05 for INV-2026-000105 (21.26) of S04 Ryan Lim with the EA method.\n2. S04 EA balance is 975.00.', 'test_data': 'Student: S04 Ryan Lim (Bukit View Primary, P5, class P5 Honesty), Singapore Citizen, EA Active, balance 975.00 SGD\nInvoice: INV-2026-000105 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Double click the Confirm button quickly.\n2. Look at the button right after the first click.\n3. Look at the transactions of the invoice, the ledger and the balance.', 'expected': '1. The Confirm button is disabled after the first click and the screen shows the Processing state.\n2. Exactly one transaction exists for the invoice.\n3. The ledger has one debit of 21.26 and the EA balance is 953.74.\n4. The invoice is Paid and the transaction and the EA leg are Succeeded.'},
    "TC-078": {'title': 'The same request sent again with the same key returns the first result', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-17: A repeat of the same key by the same Parent returns the result of the first transaction. No new transaction is created, no second debit is made and no error is shown.', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.\n2. S01 EA balance is 1,590.00.\n3. The invoice is Issued before the first request.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset\nIdempotency key: IDM-KEY-001', 'steps': '1. Send the create payment request with the key IDM-KEY-001.\n2. Send exactly the same request again with the same key.\n3. Look at both answers, the transactions, the ledger and the balance.', 'expected': '1. Both answers refer to the same transaction.\n2. Only one transaction exists and the ledger has one debit of 27.25.\n3. The second answer is not an error.\n4. The balance is 1,562.75.\n5. The invoice is Paid and the transaction and the EA leg are Succeeded.'},
    "TC-079": {'title': 'The same key can be used by two different Parents', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'API: create payment', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S25 and PAR-S25-F have valid sessions.\n2. INV-2026-000126 (X, 2.25) and INV-2026-000127 (Y, 5.83) of S25 are Issued.\n3. S25 EA balance is 730.00.', 'test_data': 'Student: S25 Nadia Karim (Bukit View Primary, P4, class P4 Kindness), Singapore Citizen, EA Active, balance 730.00 SGD\nInvoices: X = INV-2026-000126 (2.25), Y = INV-2026-000127 (5.83), Net after the R4 FAS subsidy\nIdempotency key: SHARED-KEY-001 for both', 'steps': '1. As PAR-S25 pay invoice X with the key SHARED-KEY-001.\n2. As PAR-S25-F pay invoice Y with the key SHARED-KEY-001.\n3. Look at the transactions.', 'expected': '1. Both payments are accepted and two transactions exist.\n2. Both invoices are Paid, both transactions and EA legs are Succeeded, each invoice has one ledger debit (2.25 and 5.83) and the EA balance is 721.92.'},
    "TC-080": {'title': 'A key of 100 characters is accepted', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'API: create payment', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-18: A request with a missing, empty or 101 character key is rejected and creates no transaction. A 100 character key is accepted. The error text is not defined, so the cases check that nothing ', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.\n2. The invoice is Issued and S01 EA balance is 1,590.00.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset\nIdempotency key: 100 characters', 'steps': '1. Send the create payment request with a key of exactly 100 characters.', 'expected': '1. The request is accepted and one transaction is created.\n2. The transaction and the EA leg are Succeeded, the invoice is Paid and the EA balance is 1,562.75.'},
    "TC-081": {'title': 'A key that is missing, empty or 101 characters long is refused', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'API: create payment', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-18: A request with a missing, empty or 101 character key is rejected and creates no transaction. A 100 character key is accepted. The error text is not defined, so the cases check that nothing ', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.\n2. The invoice is Issued and S01 EA balance is 1,590.00.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset\nKeys tried: none, empty, 101 characters', 'steps': '1. Send the create payment request with no key.\n2. Send it with an empty key.\n3. Send it with a key of 101 characters.\n4. Look at the transactions and the balance.', 'expected': '1. Each request is refused.\n2. No transaction is created, no debit is made, the invoice is still Issued and the EA balance is still 1,590.00.'},
    "TC-082": {'title': 'Two requests at the same time for one invoice give one payment and one refusal', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S25 has a valid session.\n2. S25 EA balance is 730.00.', 'test_data': 'Student: S25 Nadia Karim (Bukit View Primary, P4, class P4 Kindness), Singapore Citizen, EA Active, balance 730.00 SGD\nInvoice: INV-2026-000126 (Miscellaneous fee, Term 4), Issued, Gross 27.25, FAS subsidy 25.00, Net 2.25 SGD, in the seed state after a reset\nTwo requests with different keys: IDM-KEY-A and IDM-KEY-B, method EA', 'steps': '1. Send both create payment requests at the same moment.\n2. Look at both answers, the transactions, the ledger, the invoice and the balance.', 'expected': '1. One request succeeds and creates one transaction.\n2. The other request is refused with 409 and the message "A payment for this invoice is still being processed." If the first request has already finished, it is refused with "This invoice has already been paid." instead (EX-04).\n3. The ledger has one debit of 2.25, the balance is 727.75 and it is never negative.\n4. The invoice is Paid once. No money is taken without the invoice being updated.'},
    "TC-083": {'title': 'Two guardians confirming the same invoice at the same time give one payment', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'SCR-05 Review and confirm', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S25 and PAR-S25-F are signed in in two browsers, both on SCR-05 for the same INV-2026-000126 (2.25) of S25 Nadia Karim with the EA method.\n2. S25 EA balance is 730.00.', 'test_data': 'Student: S25 Nadia Karim (Bukit View Primary, P4, class P4 Kindness), Singapore Citizen, EA Active, balance 730.00 SGD\nInvoice: INV-2026-000126 (Miscellaneous fee, Term 4), Issued, Gross 27.25, FAS subsidy 25.00, Net 2.25 SGD, in the seed state after a reset\nIdempotency keys: IDM-KEY-C for PAR-S25 and IDM-KEY-D for PAR-S25-F', 'steps': '1. Confirm in both browsers at the same moment.\n2. Look at both screens, the transactions, the ledger and the balance.', 'expected': '1. One Parent sees the success screen SCR-07.\n2. The other Parent is refused with PAYMENT_PENDING or INVOICE_ALREADY_PAID and is sent to SCR-06 or the refreshed list.\n3. One transaction exists and it is Succeeded, the ledger has one debit of 2.25, the invoice is Paid and the balance is 727.75.'},
    "TC-084": {'title': 'Confirming an invoice that was paid meanwhile is refused', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'SCR-05 Review and confirm', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S25 is signed in and is on SCR-05 for INV-2026-000126 (2.25) of S25 Nadia Karim.\n2. PAR-S25-F has paid the same invoice with the EA after PAR-S25 opened SCR-05.', 'test_data': 'Student: S25 Nadia Karim (Bukit View Primary, P4, class P4 Kindness), Singapore Citizen, EA Active, balance 730.00 SGD\nInvoice: INV-2026-000126 (Miscellaneous fee, Term 4), Issued, Gross 27.25, FAS subsidy 25.00, Net 2.25 SGD, in the seed state after a reset\nPayment of PAR-S25-F before PAR-S25 confirms: EA, Succeeded, EA balance 727.75', 'steps': '1. Confirm the payment as PAR-S25.\n2. Look at the screen, the transactions and the balance.', 'expected': '1. The message "This invoice has already been paid." is shown and the list is refreshed.\n2. No second transaction is created and no second debit is made. The invoice stays Paid, the transaction of PAR-S25-F stays Succeeded and the balance is 727.75.'},
    "TC-085": {'title': 'Confirming an invoice that is waiting for another payment is refused', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'SCR-06 Pending', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. PAR-S25 is signed in and is on SCR-05 for INV-2026-000126 (2.25) of S25 Nadia Karim.\n2. PAR-S25-F has started an online payment for the same invoice and it is PaymentPending.', 'test_data': 'Student: S25 Nadia Karim (Bukit View Primary, P4, class P4 Kindness), Singapore Citizen, EA Active, balance 730.00 SGD\nInvoice: INV-2026-000126 (Miscellaneous fee, Term 4), Issued, Gross 27.25, FAS subsidy 25.00, Net 2.25 SGD, in the seed state after a reset\nTransaction of PAR-S25-F: Pending, online leg 2.25 Pending, invoice PaymentPending', 'steps': '1. Confirm the payment as PAR-S25 with the EA method.\n2. Look at the screen, the transactions and the balance.', 'expected': '1. The message "A payment for this invoice is still being processed." is shown and the Parent moves to SCR-06.\n2. No new transaction is created and the EA balance is still 730.00.\n3. The invoice is still PaymentPending and the transaction of PAR-S25-F is still Pending.'},
    "TC-086": {'title': 'Confirming an invoice that was cancelled meanwhile is refused', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'SCR-05 Review and confirm', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05', 'preconditions': '1. PAR-S18 is signed in and is on SCR-05 for INV-2026-000123 (21.26) of S18 Zachary Lee with the EA method.\n2. The invoice is set to Cancelled after SCR-05 opened.', 'test_data': 'Student: S18 Zachary Lee (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 595.00 SGD\nInvoice: INV-2026-000123 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Cancel the invoice in the data.\n2. Confirm the payment.\n3. Look at the screen, the transactions and the balance.', 'expected': '1. The message "This invoice can no longer be paid." is shown and the list is refreshed.\n2. No transaction is created and the EA balance is still 595.00.\n3. The invoice stays Cancelled.'},
    "TC-087": {'title': 'Review screen for an online payment has no EA part', 'suite': 'F9.5 Pay online', 'page': 'SCR-05 Review and confirm', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S07 is signed in and is on SCR-04 for INV-2026-000109 (21.26) of S07 Priya Nair.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset\nMethod: online', 'steps': '1. Choose online payment and continue.\n2. Read SCR-05.', 'expected': '1. SCR-05 shows the child S07 Priya Nair, the invoice number, the amount to pay 21.26 SGD and the method online.\n2. No EA amount and no EA balance after payment are shown.\n3. Nothing is created yet: no transaction exists and the invoice is still Issued.'},
    "TC-088": {'title': 'A student without an EA pays online and the invoice becomes Paid', 'suite': 'F9.5 Pay online', 'page': 'SCR-07 Payment confirmation', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. PAR-S07 is signed in and is on SCR-05 for INV-2026-000109 (21.26) of S07 Priya Nair with the online method.\n2. The sandbox provider is ready and can send a valid webhook.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset\nMethod: online', 'steps': '1. Confirm the payment.\n2. Look at the transaction, the online leg and the invoice before paying.\n3. On the provider page choose a payment method and finish with the success outcome.\n4. Wait for the webhook and return to the portal.\n5. Read SCR-07 and the data.', 'expected': '1. After the confirm, the transaction is Pending, the online leg is Pending and the invoice is PaymentPending. The Parent is sent to the provider page for 21.26 SGD.\n2. A valid webhook is recorded. The online leg is Succeeded with the ProviderTransactionId, the transaction is Succeeded and the invoice is Paid.\n3. SCR-07 shows success, a transaction reference, the time, the online part 21.26 and the total 21.26.\n4. Requested and Settled amounts are 21.26. No EA is used and the student has no EA.'},
    "TC-089": {'title': 'A student with an EA who pays online keeps the EA balance', 'suite': 'F9.5 Pay online', 'page': 'SCR-07 Payment confirmation', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S01 is signed in and is on SCR-05 for INV-2026-000101 (27.25) of S01 Nur Aisyah with the online method.\n2. S01 EA balance is 1,590.00.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset\nMethod: online', 'steps': '1. Confirm the payment and finish with the success outcome at the provider.\n2. Read the EA balance and the ledger.', 'expected': '1. The invoice is Paid by the online leg only.\n2. The EA balance is still 1,590.00 and the ledger has no entry for the payment.\n3. The transaction and the online leg are Succeeded, and the transaction has no EA leg.'},
    "TC-090": {'title': 'Provider failure returns the invoice to Issued and nothing is charged', 'suite': 'F9.5 Pay online', 'page': 'SCR-08 Payment failed', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. PAR-S07 is signed in and is on SCR-05 for INV-2026-000109 (21.26) of S07 Priya Nair with the online method.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Confirm the payment.\n2. At the provider choose the failure outcome.\n3. Return to the portal.\n4. Look at SCR-08, the leg, the transaction and the invoice.', 'expected': '1. The online leg is Failed, the transaction is Failed and the invoice is Issued.\n2. SCR-08 shows "Your payment could not be completed. No amount was deducted." with the buttons Try again and Exit.\n3. No amount is collected.'},
    "TC-091": {'title': 'Cancel on the provider page returns the invoice to Issued', 'suite': 'F9.5 Pay online', 'page': 'SCR-08 Payment failed', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. PAR-S07 is signed in and is on SCR-05 for INV-2026-000109 (21.26) of S07 Priya Nair with the online method.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Confirm the payment.\n2. On the provider page cancel the payment.\n3. Return to the portal.\n4. Look at SCR-08, the leg, the transaction and the invoice.', 'expected': '1. The online leg is Cancelled, the transaction is Cancelled and the invoice is Issued.\n2. SCR-08 shows "The payment was cancelled. No amount was deducted."\n3. No amount is collected.'},
    "TC-092": {'title': 'An expired provider payment session fails the online leg', 'suite': 'F9.5 Pay online', 'page': 'SCR-08 Payment failed', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-06: The provider payment session expires after 10 minutes, or after the value Dev gives, or when the sandbox expires it on demand.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. PAR-S07 is signed in and is on SCR-05 for INV-2026-000109 (21.26) of S07 Priya Nair with the online method.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Confirm the payment.\n2. Stay on the provider page without paying until the payment session expires.\n3. Return to the portal.\n4. Look at the leg, the transaction, the invoice and SCR-08.', 'expected': '1. The online leg is Failed and the transaction is Failed.\n2. The invoice is Issued and nothing is collected.\n3. SCR-08 shows "Your payment could not be completed. No amount was deducted."'},
    "TC-094": {'title': 'Closing the browser on the provider page keeps the payment Pending until the result arrives', 'suite': 'F9.5 Pay online', 'page': 'SCR-06 Pending', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. PAR-S07 is signed in and is on SCR-05 for INV-2026-000109 (21.26) of S07 Priya Nair with the online method.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Confirm the payment.\n2. On the provider page close the browser without paying.\n3. Sign in again as PAR-S07 and open SCR-02 of S07.\n4. Let the provider send the success result and look again.', 'expected': '1. Before the result arrives the transaction and the online leg stay Pending, the invoice is PaymentPending and the Parent sees the waiting state SCR-06.\n2. No second payment can be started.\n3. After the valid success webhook the online leg and the transaction are Succeeded and the invoice is Paid.'},
    "TC-095": {'title': 'A provider timeout keeps the leg Pending and does not mark it Failed', 'suite': 'F9.5 Pay online', 'page': 'SCR-06 Pending', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. PAR-S07 has started an online payment for INV-2026-000109 (21.26) of S07 Priya Nair and the leg is Pending.\n2. The sandbox is set to time out on every status question.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Run the reconciliation job once while the provider times out.\n2. Look at the leg, the transaction and the invoice.', 'expected': '1. The online leg stays Pending and the transaction stays Pending.\n2. The invoice stays PaymentPending.\n3. Nothing is marked Failed.'},
    "TC-096": {'title': 'No card data is stored after an online payment', 'suite': 'F9.5 Pay online', 'page': 'Database and logs', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. An online payment of INV-2026-000109 (21.26) of S07 Priya Nair has finished with the success outcome.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nSandbox test card or account used on the provider page', 'steps': '1. Search the payment tables for the test card number or account number.\n2. Search the application and webhook logs for the same value.', 'expected': '1. No card number or account number is stored in the payment tables.\n2. No card number or account number is in the logs.\n3. Only the provider references and the hash of the callback are stored.'},
    "TC-097": {'title': 'Split of EA 20.00 and online 50.63 pays a 70.63 invoice', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'SCR-07 Payment confirmation', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S02 is signed in and is on SCR-05 for INV-2026-000103 (70.63) of S02 with the split option and the default parts EA 20.00 and online 50.63.\n2. S02 EA balance is 20.00.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nMethod: SPLIT, EA 20.00, online 50.63\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Confirm the payment.\n2. On the provider page finish with the success outcome.\n3. Wait for the valid webhook and return to the portal.\n4. Read SCR-07, the legs, the transaction, the invoice, the ledger and the balance.', 'expected': '1. The EA balance falls by 20.00 to 0.00 and the EA leg is Succeeded.\n2. The online leg of 50.63 is Succeeded after a valid webhook.\n3. The transaction is Succeeded and the invoice is Paid.\n4. SCR-07 shows two parts, EA 20.00 and online 50.63, and the total 70.63.\n5. The two legs have different FundingReferences and their amounts add up to 70.63.'},
    "TC-098": {'title': 'The EA is debited before the online payment session is created', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'Function 1 and provider calls', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. A split payment of EA 20.00 and online 50.63 is confirmed for INV-2026-000103 (70.63) of S02 Aisha Rahman.\n2. PAR-S02, linked to S02, started the payment from an Issued invoice (FS 3.1.1 precondition).', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (School Meal Fee, Nov), Issued, Net 70.63 SGD, in the seed state after a reset\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Confirm the payment.\n2. Read the time of the EA debit call, of the EA leg result and of the creation of the payment session.', 'expected': '1. The EA debit is called first and the EA leg is Succeeded.\n2. The payment session at the provider is created only after the EA leg is Succeeded.\n3. The online leg is created Pending after the EA result.\n4. Before the online result arrives: the transaction is Pending, the EA leg is Succeeded, the online leg is Pending, the invoice is PaymentPending and the EA balance is already 0.00.'},
    "TC-099": {'title': 'Split with a lowered EA part of 10.00 and an online part of 60.63 pays the invoice', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'SCR-07 Payment confirmation', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-01: The EA part starts at the whole available balance. The Parent can lower it to any amount above 0 and below the payable amount, and the online part is then Net minus the EA part. AC-22 is fo', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 for INV-2026-000103 (70.63) of S02 Aisha Rahman.\n2. S02 EA balance is 20.00.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (School Meal Fee, Nov), Issued, Net 70.63 SGD, in the seed state after a reset\nMethod: SPLIT, EA 10.00, online 60.63\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Choose the split option and change the EA part to 10.00.\n2. Continue and confirm.\n3. Finish with the success outcome at the provider.\n4. Read SCR-07 and the EA balance.', 'expected': '1. The EA is debited 10.00 and the balance is 10.00.\n2. The online part is 60.63 and is Succeeded.\n3. The invoice is Paid and SCR-07 shows EA 10.00 and online 60.63.\n4. The transaction, the EA leg and the online leg are Succeeded.'},
    "TC-100": {'title': 'Review screen for a split shows both parts and the balance after payment', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'SCR-05 Review and confirm', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 for INV-2026-000103 of S02 with the split option and the default parts.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Continue to SCR-05.\n2. Read SCR-05.', 'expected': '1. SCR-05 shows the amount to pay 70.63 and the two parts EA 20.00 and online 50.63.\n2. It shows the EA balance after payment 0.00 as information only.\n3. Nothing is debited on SCR-05: the EA balance is still 20.00 and no new transaction exists.'},
    "TC-101": {'title': 'While the online part is pending the waiting screen says the EA part is already taken', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'SCR-06 Pending', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. A split payment of EA 20.00 and online 50.63 is confirmed for INV-2026-000103 (70.63) of S02 Aisha Rahman.\n2. The EA leg is Succeeded and the online leg is Pending at the provider.\n3. PAR-S02, linked to S02, started the payment from an Issued invoice. The transaction is Pending and the invoice is PaymentPending.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (School Meal Fee, Nov), Issued, Net 70.63 SGD, in the seed state after a reset\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Close the browser on the provider page.\n2. Sign in again as PAR-S02 and open the invoice.\n3. Read SCR-06.', 'expected': '1. SCR-06 shows the waiting state with a temporary reference.\n2. It states that the EA part 20.00 has already been taken.\n3. The Parent cannot start another payment for the invoice.\n4. The transaction is Pending, the EA leg is Succeeded, the online leg is Pending and the invoice is PaymentPending. The EA balance stays 0.00 until the result.'},
    "TC-102": {'title': 'EA debit fails before the online part: no payment session and no online charge', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'SCR-04 Choose payment method', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S02 is signed in and is on SCR-05 for INV-2026-000103 of S02 with the split option (EA 20.00, online 50.63).\n2. S02 EA balance is 20.00 when SCR-05 opens.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nBalance changed to 10.00 before the confirm\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Without leaving SCR-05 set the EA balance of S02 to 10.00 in Function 1.\n2. Confirm the payment.\n3. Look at the legs, the transaction, the invoice, the provider calls and the screen.', 'expected': '1. The EA leg is Failed and the transaction is Failed.\n2. No payment session is created at the provider and nothing is collected online.\n3. The invoice is Issued and the EA balance is 10.00.\n4. The Parent sees "Your Education Account balance is not enough for this amount. You can pay the rest online." and goes back to the choice of method.'},
    "TC-103": {'title': 'Online failure after the EA debit returns the EA part', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'SCR-08 Payment failed', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. A split payment of EA 20.00 and online 50.63 is confirmed for INV-2026-000103 of S02.\n2. The EA leg is Succeeded and the EA balance is 0.00.\n3. PAR-S02, linked to S02, started the payment from the Issued invoice INV-2026-000103 (FS 3.1.1 precondition).', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. At the provider choose the failure outcome.\n2. Return to the portal.\n3. Look at SCR-08, the legs, the transaction, the invoice, the ledger and the balance.', 'expected': '1. The online leg is Failed. The EA leg is Reversed and the reversal ID is stored.\n2. The transaction is Failed and the invoice is Issued.\n3. The ledger shows the debit of 20.00 and the reversal of 20.00. The EA balance is 20.00 again.\n4. SCR-08 shows "Your online payment could not be completed. The amount taken from the Education Account has been returned." with the buttons Try again and Exit.'},
    "TC-104": {'title': 'Cancel at the provider after the EA debit returns the EA part', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'SCR-08 Payment failed', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-14: When the Parent cancels at the provider, the transaction and the online leg are Cancelled. When the online part fails or expires, the transaction is Failed. In both cases the EA leg is Reve', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. A split payment of EA 20.00 and online 50.63 is confirmed for INV-2026-000103 of S02.\n2. The EA leg is Succeeded.\n3. PAR-S02, linked to S02, started the payment from the Issued invoice INV-2026-000103 (FS 3.1.1 precondition).', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. On the provider page cancel the payment.\n2. Return to the portal.\n3. Look at SCR-08, the legs, the transaction, the invoice, the ledger and the balance.', 'expected': '1. The online leg is Cancelled and the EA leg is Reversed.\n2. The transaction is Cancelled and the invoice is Issued.\n3. The EA balance is 20.00 again.\n4. SCR-08 shows "Your online payment could not be completed. The amount taken from the Education Account has been returned.", the message for a split where the EA was taken.'},
    "TC-105": {'title': 'An expired provider session after the EA debit returns the EA part', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'SCR-08 Payment failed', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-06: The provider payment session expires after 10 minutes, or after the value Dev gives, or when the sandbox expires it on demand.', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. A split payment of EA 20.00 and online 50.63 is confirmed for INV-2026-000103 of S02.\n2. The EA leg is Succeeded.\n3. PAR-S02, linked to S02, started the payment from the Issued invoice INV-2026-000103 (FS 3.1.1 precondition).', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Stay on the provider page without paying until the payment session expires.\n2. Return to the portal.\n3. Look at SCR-08, the legs, the transaction, the invoice and the balance.', 'expected': '1. The online leg is Failed and the EA leg is Reversed.\n2. The transaction is Failed and the invoice is Issued.\n3. The EA balance is 20.00 again and SCR-08 shows "Your online payment could not be completed. The amount taken from the Education Account has been returned."'},
    "TC-107": {'title': 'A failed reversal moves the payment to ReconciliationRequired', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'SCR-06 Pending', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-28: The system retries a failed reversal up to a limit N set by Dev, then sets the leg and transaction to ReconciliationRequired. QA checks that retries stop.', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. A split payment of EA 20.00 and online 50.63 is confirmed for INV-2026-000103 of S02.\n2. The EA leg is Succeeded.\n3. Function 1 is set to fail every reversal.\n4. PAR-S02, linked to S02, started the payment from the Issued invoice INV-2026-000103 (FS 3.1.1 precondition).', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. At the provider choose the failure outcome.\n2. Return to the portal.\n3. Wait until the system stops trying.\n4. Look at the screen, the legs, the transaction, the invoice, the alerts and the number of reversal attempts.', 'expected': '1. The EA leg and the transaction are ReconciliationRequired.\n2. The invoice stays PaymentPending and is not Paid.\n3. SCR-06 shows the verifying state.\n4. An operations alert is raised.\n5. The system stops retrying after a limited number of attempts.\n6. The ledger keeps the debit of 20.00 and has no reversal entry, so the EA balance is not restored by the system and stays 0.00.'},
    "TC-108": {'title': 'A failure after the EA debit and before the online session is cleaned up by the sweep', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'Orphan sweep job', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-08: The sweep finds a Pending transaction with an EA leg Succeeded and no online leg after X minutes and reverses the EA part. QA can run the sweep on demand.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. A split payment is confirmed for INV-2026-000103 (70.63) of S02 Aisha Rahman.\n2. The system is stopped right after the EA leg is Succeeded, so no online leg exists.\n3. PAR-S02, linked to S02, started the payment from an Issued invoice (FS 3.1.1 precondition).', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (School Meal Fee, Nov), Issued, Net 70.63 SGD, in the seed state after a reset\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Wait X minutes (or run the sweep on demand).\n2. Look at the EA leg, the transaction, the invoice, the ledger and the balance.', 'expected': '1. The sweep finds the Pending transaction with an EA leg Succeeded and no online leg.\n2. The EA part is reversed. The EA leg is Reversed, the transaction is Failed and the invoice is Issued.\n3. The EA balance is 20.00 again.'},
    "TC-109": {'title': 'The sweep leaves a split payment alone when the online leg exists', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'Orphan sweep job', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-08: The sweep finds a Pending transaction with an EA leg Succeeded and no online leg after X minutes and reverses the EA part. QA can run the sweep on demand.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. A split payment is confirmed for INV-2026-000103 (70.63) of S02 Aisha Rahman.\n2. The EA leg is Succeeded and the online leg is Pending at the provider.\n3. PAR-S02, linked to S02, started the payment from an Issued invoice (FS 3.1.1 precondition).', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (School Meal Fee, Nov), Issued, Net 70.63 SGD, in the seed state after a reset\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Wait X minutes (or run the sweep on demand).\n2. Look at the EA leg, the online leg and the ledger.', 'expected': '1. The EA leg is still Succeeded and no reversal is made.\n2. The online leg is still Pending.\n3. The transaction is still Pending and the invoice is still PaymentPending.'},
    "TC-110": {'title': 'A late provider success after the EA was returned is not paid and goes to manual handling', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'SCR-06 Pending', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-04, ENV-R9-05', 'preconditions': '1. Seed state: the transaction PAY-20261019-000006 of INV-2026-000103 (S02 Aisha Rahman) is Failed. Its EA leg 20.00 is Reversed and its online leg 70.63 less 20.00 = 50.63 is Failed (sbx_pi_2026101900008, PAYMENT_DECLINED). The invoice is Issued (AC-20).\n2. The sandbox can send a late success for the online payment.\n3. The provider session was cancelled or allowed to expire before the EA part was reversed (EX-12).', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeeded online leg: FND-20261019-000006-2, provider transaction sbx_pi_2026101900008', 'steps': '1. Send a valid success webhook for sbx_pi_2026101900008 (FND-20261019-000006-2).\n2. Look at the online leg, the invoice, the alerts and the balance.', 'expected': '1. The online leg is ReconciliationRequired.\n2. The invoice does not become Paid by itself.\n3. An operations alert is raised.\n4. The EA part stays reversed and no online refund is made.\n5. The EA balance stays 20.00.'},
    "TC-111": {'title': 'A valid callback is recorded at once and processed later', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Webhook endpoint', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-19: A callback with a wrong or missing signature is rejected with a 4xx response, a security log entry is written and nothing is stored in the webhook receipt. A valid callback gets a 2xx respo', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. An online payment is started for INV-2026-000109 (21.26) of S07 Priya Nair. The online leg is Pending with the FundingReference FR-ONL-01.\n2. The processing job can be paused so the order of steps can be seen.\n3. PAR-S07, linked to S07, started the payment from an Issued invoice. The transaction is Pending, the online leg is Pending (21.26) and the invoice is PaymentPending.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nCallback: success, valid signature, ProviderCode SANDBOX, ProviderEventId EVT-001, FundingReference FR-ONL-01\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset\nCallback amount: 21.26 SGD', 'steps': '1. Pause the processing job.\n2. Send the valid callback to the webhook.\n3. Read the response and the webhook receipt.\n4. Resume the processing job.\n5. Read the receipt, the online leg, the transaction and the invoice.', 'expected': '1. The webhook answers with a 2xx response at once and does not wait for the processing.\n2. The receipt exists with ProcessingStatus Received and an empty ProcessedAt.\n3. After the job runs the receipt is Processed with ProcessedAt set and linked to the online leg.\n4. The online leg is Succeeded, the transaction is Succeeded and the invoice is Paid.'},
    "TC-112": {'title': 'A callback with a wrong signature is rejected and changes nothing', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Webhook endpoint', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-19: A callback with a wrong or missing signature is rejected with a 4xx response, a security log entry is written and nothing is stored in the webhook receipt. A valid callback gets a 2xx respo', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. An online payment is started for INV-2026-000109 (21.26) of S07 Priya Nair. The online leg is Pending with the FundingReference FR-ONL-01.\n2. PAR-S07, linked to S07, started the payment from an Issued invoice. The transaction is Pending, the online leg is Pending (21.26) and the invoice is PaymentPending.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nCallback: success, signature made with a wrong secret\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset\nCallback amount: 21.26 SGD', 'steps': '1. Send the callback with the wrong signature.\n2. Read the response, the webhook receipts, the security log, the online leg and the invoice.', 'expected': '1. The callback is rejected with a 4xx response.\n2. A security log entry is written.\n3. No receipt is stored for it.\n4. The online leg is still Pending and the invoice is still PaymentPending.\n5. The transaction is still Pending.'},
    "TC-113": {'title': 'A callback without a signature is rejected', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Webhook endpoint', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-19: A callback with a wrong or missing signature is rejected with a 4xx response, a security log entry is written and nothing is stored in the webhook receipt. A valid callback gets a 2xx respo', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. An online payment is started for INV-2026-000109 (21.26) of S07 Priya Nair. The online leg is Pending with the FundingReference FR-ONL-01.\n2. PAR-S07, linked to S07, started the payment from an Issued invoice. The transaction is Pending, the online leg is Pending (21.26) and the invoice is PaymentPending.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nCallback: success, no signature header\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset\nCallback amount: 21.26 SGD', 'steps': '1. Send the callback without the signature.\n2. Read the response, the receipts, the security log and the online leg.', 'expected': '1. The callback is rejected with a 4xx response and a security log entry is written.\n2. No receipt is stored. The online leg and the transaction are still Pending and the invoice is still PaymentPending.'},
    "TC-114": {'title': 'A callback whose content was changed after signing is rejected', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Webhook endpoint', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-19: A callback with a wrong or missing signature is rejected with a 4xx response, a security log entry is written and nothing is stored in the webhook receipt. A valid callback gets a 2xx respo', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. An online payment is started for INV-2026-000109 (21.26) of S07 Priya Nair. The online leg is Pending with the FundingReference FR-ONL-01.\n2. PAR-S07, linked to S07, started the payment from an Issued invoice. The transaction is Pending, the online leg is Pending (21.26) and the invoice is PaymentPending.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nCallback: valid signature of a failure payload, body changed to success\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset\nCallback amount: 21.26 SGD', 'steps': '1. Sign a failure payload.\n2. Change the body to a success payload and keep the signature.\n3. Send the callback.\n4. Read the response and the online leg.', 'expected': '1. The callback is rejected with a 4xx response and a security log entry is written.\n2. The online leg and the transaction are still Pending and the invoice is still PaymentPending.'},
    "TC-115": {'title': 'The same event sent twice is applied once', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Webhook endpoint', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. An online payment is started for INV-2026-000109 (21.26) of S07 Priya Nair. The online leg is Pending with the FundingReference FR-ONL-01.\n2. PAR-S07, linked to S07, started the payment from an Issued invoice. The transaction is Pending, the online leg is Pending (21.26) and the invoice is PaymentPending.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nCallback: success, valid signature, ProviderCode SANDBOX, ProviderEventId EVT-002\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset\nCallback amount: 21.26 SGD', 'steps': '1. Send the valid callback.\n2. Let it be processed.\n3. Send exactly the same callback again.\n4. Send the seeded event sbx_evt_2026072000001 (S16 Darren Ho, FND-20260720-000003-2) again.\n5. Read the receipts, the online leg, the transaction and the audit log.', 'expected': '1. Only one receipt exists for ProviderCode SANDBOX and ProviderEventId EVT-002.\n2. The online leg and the transaction changed to Succeeded once and the invoice changed to Paid once.\n3. The second callback has no further effect and no extra audit entry.\n4. The replay of the seeded event sbx_evt_2026072000001 has no effect: R9-WHK-0001 stays Processed, INV-2026-000121 stays Paid and the EA balance of S16 stays 875.00 (AC-10).'},
    "TC-119": {'title': 'Only a hash of the callback is stored', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Database and logs', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. An online payment is started for INV-2026-000109 (21.26) of S07 Priya Nair. The online leg is Pending with the FundingReference FR-ONL-01.\n2. PAR-S07, linked to S07, started the payment from an Issued invoice. The transaction is Pending, the online leg is Pending (21.26) and the invoice is PaymentPending.', 'test_data': "Callback: success, valid signature, with an extra field 'note' = ZZ-RAW-PAYLOAD-MARKER\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset\nCallback amount: 21.26 SGD", 'steps': '1. Send the valid callback and let it be processed.\n2. Search the webhook receipt table and the logs for the marker text.\n3. Read the PayloadHash of the receipt.', 'expected': '1. The marker text is not stored in the receipt table and not in the logs.\n2. PayloadHash holds a SHA-256 value of 32 bytes.\n3. No card data is stored.'},
    "TC-120": {'title': 'A lost webhook is replaced by the provider status query: success', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Reconciliation job', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-07: SIT has a threshold of T minutes and a polling interval of P minutes set by Dev. QA can run the reconciliation job on demand. The cases use T and P.', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. An online payment is started for INV-2026-000109 (21.26) of S07 Priya Nair. The online leg is Pending with the FundingReference FR-ONL-01.\n2. The provider has the payment as successful but no callback is sent.\n3. PAR-S07, linked to S07, started the payment from an Issued invoice. The transaction is Pending, the online leg is Pending (21.26) and the invoice is PaymentPending.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Run the reconciliation job (or wait for the polling interval).\n2. Read the online leg, the transaction and the invoice.', 'expected': '1. The system asks the provider about the Pending leg.\n2. The online leg is Succeeded, the transaction is Succeeded and the invoice is Paid.'},
    "TC-121": {'title': 'A lost webhook is replaced by the provider status query: failure', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Reconciliation job', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-07: SIT has a threshold of T minutes and a polling interval of P minutes set by Dev. QA can run the reconciliation job on demand. The cases use T and P.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. An online payment is started for INV-2026-000109 (21.26) of S07 Priya Nair. The online leg is Pending with the FundingReference FR-ONL-01.\n2. The provider has the payment as failed but no callback is sent.\n3. PAR-S07, linked to S07, started the payment from an Issued invoice. The transaction is Pending, the online leg is Pending (21.26) and the invoice is PaymentPending.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Run the reconciliation job (or wait for the polling interval).\n2. Read the online leg, the transaction and the invoice.', 'expected': '1. The online leg is Failed and the transaction is Failed.\n2. The invoice is Issued and nothing is collected.'},
    "TC-122": {'title': 'A Pending leg that stays unclear beyond the threshold moves to ReconciliationRequired', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'SCR-06 Pending', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-07: SIT has a threshold of T minutes and a polling interval of P minutes set by Dev. QA can run the reconciliation job on demand. The cases use T and P.', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. An online payment is started for INV-2026-000109 (21.26) of S07 Priya Nair. The online leg is Pending with the FundingReference FR-ONL-01.\n2. The provider does not answer status questions and sends no callback.\n3. PAR-S07, linked to S07, started the payment from an Issued invoice. The transaction is Pending, the online leg is Pending (21.26) and the invoice is PaymentPending.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nThreshold: T minutes\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Wait longer than T minutes while the reconciliation job runs.\n2. Read the online leg, the transaction, the invoice and the alerts.\n3. Open the invoice as PAR-S07.', 'expected': '1. Before T minutes the leg stays Pending and is never set to Failed.\n2. After T minutes the leg and the transaction are ReconciliationRequired.\n3. The invoice stays PaymentPending and an operations alert is raised.\n4. The Parent sees the verifying state on SCR-06.'},
    "TC-123": {'title': 'A webhook and a status query that arrive together are applied once', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Reconciliation job', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. An online payment is started for INV-2026-000109 (21.26) of S07 Priya Nair. The online leg is Pending with the FundingReference FR-ONL-01.\n2. PAR-S07, linked to S07, started the payment from an Issued invoice. The transaction is Pending, the online leg is Pending (21.26) and the invoice is PaymentPending.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nWebhook success and status query success at the same moment\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Send the valid success callback and run the reconciliation job at the same moment.\n2. Read the online leg, the transaction, the invoice and the audit log.', 'expected': '1. The online leg changes to Succeeded once and the invoice changes to Paid once.\n2. There is no second state change in the audit log.'},
    "TC-125": {'title': 'The waiting screen shows the pending notice, a temporary reference and the actions', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-06 Pending', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. PAR-S08 is signed in. INV-2026-000111 of S08 Farhan Ismail has the seeded Pending online payment PAY-20261020-000004 (27.25, FND-20261020-000004-1).', 'test_data': 'Student: S08 Farhan Ismail (Meridian Secondary, Sec 2, class Sec 2 Integrity), Singapore Citizen, EA Active, balance 1,370.00 SGD\nInvoice: INV-2026-000111 (27.25)', 'steps': '1. Open SCR-02 of S08 and open the waiting state of INV-2026-000111 (or return to the portal after the provider page of a new online payment).\n2. Read SCR-06.', 'expected': '1. SCR-06 shows that the payment is pending.\n2. It shows a temporary reference.\n3. It has the actions to refresh the status and to go back to SCR-02.\n4. The transaction is Pending, the online leg is Pending and the invoice is PaymentPending.'},
    "TC-126": {'title': 'Refreshing the waiting screen shows the success screen after the result arrives', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-06 Pending', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04', 'preconditions': '1. PAR-S08 is on SCR-06 for the seeded Pending online payment PAY-20261020-000004 of INV-2026-000111 (27.25).', 'test_data': 'Student: S08 Farhan Ismail (Meridian Secondary, Sec 2, class Sec 2 Integrity), Singapore Citizen, EA Active, balance 1,370.00 SGD', 'steps': '1. Send the valid success callback for FND-20261020-000004-1 (new ProviderEventId).\n2. Use the refresh action of SCR-06.', 'expected': '1. SCR-07 opens with the success result, the reference and the online part 27.25.\n2. The online leg and the transaction are Succeeded and the invoice is Paid.'},
    "TC-127": {'title': 'A Parent who comes back to a pending invoice cannot start a second payment', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-02 Outstanding fees', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-03: SCR-02 lists invoices in Issued (payable) and PaymentPending (shown as Pending, not selectable). Paid, Cancelled and Draft are not listed. The total owed is the sum of Net of the listed inv', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S08 has the seeded Pending online payment PAY-20261020-000004 for INV-2026-000111 (27.25).', 'test_data': 'Student: S08 Farhan Ismail (Meridian Secondary, Sec 2, class Sec 2 Integrity), Singapore Citizen, EA Active, balance 1,370.00 SGD\nInvoice: INV-2026-000111 (PaymentPending, open transaction PAY-20261020-000004)\nIdempotency key of the new request: RETRY-KEY-127', 'steps': '1. Sign out and sign in again as PAR-S08.\n2. Open SCR-02 of S08 and try to select INV-2026-000111.\n3. Send a create payment request for the same invoice with a new key.', 'expected': '1. The invoice shows the status Pending and the waiting state can be opened.\n2. The invoice cannot be selected for a new payment.\n3. The request is refused with 409 and the message "A payment for this invoice is still being processed."; no new transaction exists.\n4. The transaction is still Pending and the invoice is still PaymentPending.'},
    "TC-128": {'title': 'The verifying state does not say the payment failed and offers no retry', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-06 Pending', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. A split payment of INV-2026-000103 (70.63) of S02 Aisha Rahman is ReconciliationRequired because the reversal failed.\n2. PAR-S02, linked to S02, started the payment from an Issued invoice and the EA part of 20.00 was debited.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nSeed display example without fault injection: S05 Chen Xin Yi, INV-2026-000106, PAY-20261021-000005 (EA 27.25 ReconciliationRequired, AC-18).\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Open SCR-06 as PAR-S02.\n2. Read the text and the actions.', 'expected': '1. SCR-06 shows the verifying state, not a failure.\n2. It names the EA part that was taken.\n3. No Try again action is offered.\n4. The transaction and the EA leg are ReconciliationRequired, the invoice stays PaymentPending and an operations alert exists.\n5. The EA part of 20.00 is not restored: the EA balance stays 0.00.'},
    "TC-129": {'title': 'The success screen of an EA payment shows reference, time, part and total', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-07 Payment confirmation', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03', 'preconditions': '1. PAR-S01 has just paid INV-2026-000101 (27.25) of S01 Nur Aisyah with the EA.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset', 'steps': '1. Read SCR-07.\n2. Use the action to go back to SCR-02.', 'expected': '1. SCR-07 shows the success status, the transaction reference, the time of payment, the EA part 27.25 and the total 27.25.\n2. It offers to download or print the receipt and to go back to SCR-02.\n3. The transaction and the EA leg are Succeeded, the invoice is Paid and the EA balance is 1,562.75.'},
    "TC-130": {'title': 'The success screen of a split payment shows both parts', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-07 Payment confirmation', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03', 'preconditions': '1. PAR-S02 has just paid INV-2026-000103 of S02 with a split of EA 20.00 and online 50.63.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Read SCR-07.', 'expected': '1. SCR-07 shows the EA part 20.00 and the online part 50.63, each with its settled amount.\n2. The settled amounts add up to the total 70.63.\n3. The transaction, the EA leg and the online leg are Succeeded, the invoice is Paid and the EA balance is 0.00.'},
    "TC-131": {'title': 'The receipt PDF of an EA payment can be downloaded', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-07 Payment confirmation', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-10: The transaction reference is unique, at most 50 characters and follows PAY-YYYYMMDD-XXXXXX, where YYYYMMDD is the payment date in SGT. The receipt PDF shows the reference, the paid at time ', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03', 'preconditions': '1. PAR-S13 is signed in. The seed has the EA payment PAY-20261008-000002 of INV-2026-000119 (Paid) with its receipt (AC-13).', 'test_data': 'Student: S13 Amira Hassan (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 558.74 SGD\nTransaction: PAY-20261008-000002 (R9-TXN-0002), invoice INV-2026-000119, EA 21.26 Succeeded on 08/10/2026 10:12 SGT', 'steps': '1. Use the download receipt action of PAY-20261008-000002 (SCR-07, or the receipt request if the Paid invoice is not listed, O11).\n2. Open the PDF.', 'expected': '1. A PDF file is downloaded and opens.\n2. It shows the transaction reference PAY-20261008-000002 and the EA part 21.26 with the total 21.26.'},
    "TC-132": {'title': 'The receipt PDF of a split payment shows two parts', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-07 Payment confirmation', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-10: The transaction reference is unique, at most 50 characters and follows PAY-YYYYMMDD-XXXXXX, where YYYYMMDD is the payment date in SGT. The receipt PDF shows the reference, the paid at time ', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03', 'preconditions': '1. PAR-S16 is signed in. The seed has the split payment PAY-20260720-000003 of INV-2026-000121 (Paid): EA 10.00 and online 11.26 (AC-13).', 'test_data': 'Student: S16 Darren Ho (Bukit View Primary, P5, class P5 Honesty), Singapore Citizen, EA Active, balance 875.00 SGD\nTransaction: PAY-20260720-000003 (R9-TXN-0003): EA 10.00 Succeeded, online 11.26 Succeeded (sbx_pi_2026072000004), total 21.26', 'steps': '1. Use the download receipt action of PAY-20260720-000003 (SCR-07, or the receipt request if the Paid invoice is not listed, O11).\n2. Open the PDF.', 'expected': '1. The PDF shows the transaction reference PAY-20260720-000003.\n2. It shows two parts, EA 10.00 and online 11.26, and the total 21.26.'},
    "TC-133": {'title': 'The receipt can be printed', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-07 Payment confirmation', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03', 'preconditions': '1. PAR-S13 is signed in. The seed has the EA payment PAY-20261008-000002 of INV-2026-000119 (Paid) with its receipt.', 'test_data': 'Student: S13 Amira Hassan (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 558.74 SGD', 'steps': '1. Use the print receipt action of PAY-20261008-000002.\n2. Look at the print preview.', 'expected': '1. The print preview shows the same content as the receipt: reference, parts and total.'},
    "TC-135": {'title': 'The paid at time is shown in Singapore time', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-07 Payment confirmation', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S13 is signed in. The seed has the EA payment PAY-20261008-000002 of INV-2026-000119.', 'test_data': 'Student: S13 Amira Hassan (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 558.74 SGD\nCompletedAt stored in UTC: 08/10/2026 02:12 (the seed time 10:12 SGT minus 8 hours)', 'steps': '1. Read the CompletedAt value of PAY-20261008-000002 in the database.\n2. Read the Paid at time on SCR-07 or on the receipt of PAY-20261008-000002.', 'expected': '1. The database value is in UTC (02:12).\n2. SCR-07 or the receipt shows the same moment in SGT, eight hours later: 08/10/2026 10:12.'},
    "TC-136": {'title': 'The failure screen of an online payment shows the message, the reason and the actions', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-08 Payment failed', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02', 'preconditions': '1. PAR-S07 is signed in. An online payment of INV-2026-000109 (21.26) of S07 Priya Nair has failed at the provider.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Read SCR-08.', 'expected': '1. SCR-08 shows "Your payment could not be completed. No amount was deducted."\n2. It shows a short friendly reason and the transaction reference.\n3. It has the actions Try again and Exit.\n4. It does not mention an EA return because no EA part was taken.\n5. The transaction and the online leg are Failed and the invoice is Issued.'},
    "TC-137": {'title': 'The failure screen of a split payment says the EA part was returned', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-08 Payment failed', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03', 'preconditions': '1. A split payment of INV-2026-000103 (70.63) of S02 Aisha Rahman has failed at the provider and the EA part was reversed.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Read SCR-08.', 'expected': '1. SCR-08 shows "Your online payment could not be completed. The amount taken from the Education Account has been returned."\n2. It shows the transaction reference and the actions Try again and Exit.\n3. The transaction is Failed, the EA leg is Reversed, the invoice is Issued and the EA balance is back to 20.00.'},
    "TC-138": {'title': 'The failure message hides technical details', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-08 Payment failed', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03', 'preconditions': '1. A payment fails for each of these reasons: Function 1 error, provider failure, provider session refused.', 'test_data': 'Three failed payments: Function 1 error (S09 Jun Hao Wong, INV-2026-000112), provider failure (S07 Priya Nair, INV-2026-000109), provider session refused (S01 Nur Aisyah, INV-2026-000101)', 'steps': '1. Read SCR-08 for each failed payment.\n2. Look at the page text and the response of the status request.', 'expected': '1. Each screen shows only the friendly message of section 5.1.\n2. No stack trace, SQL text, HTTP code, internal failure code or provider raw message is shown.'},
    "TC-139": {'title': 'Exit on the failure screen returns to the invoice list with the invoice still Issued', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-02 Outstanding fees', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02', 'preconditions': '1. PAR-S07 is on SCR-08 after a failed online payment of INV-2026-000109 (21.26) of S07 Priya Nair.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account', 'steps': '1. Use the Exit action.\n2. Read the invoice list.', 'expected': '1. SCR-02 opens and the invoice is listed as Issued and can be selected again.\n2. No amount was collected.'},
    "TC-140": {'title': 'Try again after a failure creates a new transaction with a new key and can succeed', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-07 Payment confirmation', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. A split payment of INV-2026-000103 of S02 failed at the provider and the EA part was reversed. The EA balance is 20.00 and the invoice is Issued.\n2. PAR-S02 is on SCR-08.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (70.63)\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Use Try again.\n2. Choose the split option and confirm.\n3. Finish with the success outcome at the provider.\n4. Read the transactions of the invoice, the ledger and SCR-07.', 'expected': '1. Try again opens SCR-04.\n2. A second transaction is created with a new idempotency key. The first transaction stays Failed in the history.\n3. The second payment succeeds and the invoice is Paid.\n4. The ledger shows the first debit, its reversal and one new debit of 20.00 (the seeded pair 8000024 and 8000026 is older history). The balance is 0.00.'},
    "TC-141": {'title': 'No retry is possible while the EA part has not been returned', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-06 Pending', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05, ENV-R9-06', 'preconditions': '1. A split payment of INV-2026-000103 (70.63) of S02 Aisha Rahman is ReconciliationRequired because the reversal failed. The invoice is PaymentPending.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nIdempotency key of the new request: RETRY-KEY-141\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. Open the invoice list as PAR-S02.\n2. Try to start a new payment for the invoice.\n3. Send a create payment request with a new key.', 'expected': '1. The invoice cannot be selected for a new payment.\n2. The request is refused with 409 and the message "A payment for this invoice is still being processed."\n3. No new transaction exists and no second EA debit is made.\n4. The transaction and the EA leg stay ReconciliationRequired, the invoice stays PaymentPending and the EA balance stays 0.00.'},
    "TC-142": {'title': 'A session that ends before the confirm creates no transaction', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-05 Review and confirm', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-05: The portal session ends after 10 minutes of inactivity in SIT, or after the value Dev gives. The cases use the value that is configured.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05', 'preconditions': '1. PAR-S01 is signed in and is on SCR-05 for INV-2026-000101 (27.25) of S01 Nur Aisyah.\n2. The idle session timeout is known (value from Dev).', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset', 'steps': '1. Wait without activity until the session times out.\n2. Confirm the payment.\n3. Look at the screen, the transactions and the balance.', 'expected': '1. The Parent sees "Your session has expired. Please sign in again." and is sent to the Singpass sign in.\n2. No transaction is created, the invoice is still Issued and the EA balance is 1,590.00.'},
    "TC-143": {'title': 'A session that ends after the confirm does not stop the payment', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-06 Pending', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-05: The portal session ends after 10 minutes of inactivity in SIT, or after the value Dev gives. The cases use the value that is configured.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. PAR-S07 has confirmed an online payment of INV-2026-000109 (21.26) of S07 Priya Nair and is on the provider page.', 'test_data': 'Student: S07 Priya Nair (Bukit View Primary, P3, class P3 Respect), Permanent Resident, no Education Account\nInvoice: INV-2026-000109 (Miscellaneous fee, Term 4), Issued, Net 21.26 SGD, in the seed state after a reset', 'steps': '1. Wait until the portal session times out while the provider page is open.\n2. Finish the payment with the success outcome at the provider.\n3. Sign in again as PAR-S07 and open the invoice.', 'expected': '1. The transaction is still processed by the provider result: the online leg and the transaction are Succeeded and the invoice is Paid.\n2. After the new sign in, the Parent sees the current state of the payment.'},
    "TC-144": {'title': 'A system error on confirm shows a safe message and changes no data', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-05 Review and confirm', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S01 is signed in and is on SCR-05 for INV-2026-000101 (27.25) of S01 Nur Aisyah with the EA method.\n2. A Function 9 service is set to return an error when the transaction is created.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset', 'steps': '1. Confirm the payment.\n2. Look at the screen, the transactions, the ledger and the invoice.', 'expected': '1. The Parent sees "Something went wrong. Please try again later." and can try again.\n2. No transaction is created, no debit is made and the invoice is still Issued.'},
    "TC-145": {'title': 'The seed data follows every invoice rule of BR-F9-12', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. R9_seed.sql is loaded in SIT (31 invoices and 32 lines, see the Seed Data sheet).', 'test_data': 'Seed Data sheet: Invoices and Invoice lines', 'steps': '1. Run a check for lines whose school differs from the invoice school.\n2. Run a check for repeated StudentChargeId.\n3. Run a check for Net different from Gross minus Subsidy on invoices and lines.\n4. Run a check for Net not above 0 on invoices that are not Draft.\n5. Run a check for negative amounts, and for lines where Gross is not above 0 or Subsidy is not in the range 0 up to below Gross.', 'expected': '1. Each check returns no rows.\n2. The invoice amount equals the sum of its line amounts, for example INV-2026-000114: 36.33 + 10.90 = 47.23 Gross, 25.00 subsidy, 22.23 Net.'},
    "TC-146": {'title': 'An Issued invoice with Net 0.00 is refused and a Draft with Net 0.00 is accepted', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.', 'test_data': 'Invoice rows: status Issued with Net 0.00; status Draft with Net 0.00; status Issued with Net 0.01', 'steps': '1. Insert the Issued invoice with Net 0.00.\n2. Insert the Draft invoice with Net 0.00.\n3. Insert the Issued invoice with Net 0.01.', 'expected': '1. The Issued invoice with Net 0.00 is refused by the database.\n2. The Draft invoice with Net 0.00 is accepted.\n3. The Issued invoice with Net 0.01 is accepted.'},
    "TC-147": {'title': 'A line with Subsidy equal to Gross is refused and Subsidy just below Gross is accepted', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.', 'test_data': 'Line rows: Gross 50.00 with Subsidy 50.00; Gross 50.00 with Subsidy 49.99; Gross 50.00 with Subsidy 0.00', 'steps': '1. Insert the line with Subsidy 50.00.\n2. Insert the line with Subsidy 49.99.\n3. Insert the line with Subsidy 0.00.', 'expected': '1. The line with Subsidy 50.00 is refused (Net would be 0.00).\n2. The lines with Subsidy 49.99 and 0.00 are accepted with Net 0.01 and 50.00.'},
    "TC-148": {'title': 'A student charge cannot be placed on two invoices', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-27: StudentChargeId stays unique across all invoices, including Cancelled ones.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.\n2. Charge CH01 (3752f7c8-2dd1-575f-93db-86b05c58881f) is on a line of the Issued invoice INV-2026-000101. Charge AX03 (08000000-0000-0000-0004-000000000003) is on a line of the Cancelled invoice INV-2026-000110.', 'test_data': 'StudentChargeId: 3752f7c8-2dd1-575f-93db-86b05c58881f (CH01), 08000000-0000-0000-0004-000000000003 (AX03)', 'steps': '1. Insert a line of a new invoice with StudentChargeId of CH01.\n2. Insert a line of a new invoice with StudentChargeId of AX03.', 'expected': '1. Both inserts are refused as duplicates of StudentChargeId.'},
    "TC-149": {'title': 'A line from another school than the invoice is refused', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.', 'test_data': 'Invoice INV-2026-000101 of Meridian Secondary; line whose charge CH02 (d41a5fcf-d3a3-524a-9933-e2cd68129261) belongs to Bukit View Primary', 'steps': '1. Insert the line of CH02 (Bukit View Primary) into the invoice INV-2026-000101 (Meridian Secondary).', 'expected': '1. The insert is refused because every line must belong to the school of the invoice.'},
    "TC-150": {'title': 'Negative amounts are refused', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.', 'test_data': 'Rows with Gross -1.00, Subsidy -1.00 or Net -1.00', 'steps': '1. Insert an invoice with a negative Gross.\n2. Insert a line with a negative Subsidy.\n3. Insert an invoice with a negative Net.', 'expected': '1. Each insert is refused.'},
    "TC-151": {'title': 'Date fields follow the invoice status', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.', 'test_data': 'Invoice rows: Issued without DueDate; Issued without IssuedAt; Issued with PaidAt; Paid with PaidAt; Cancelled with CancelledAt', 'steps': '1. Insert the Issued invoice without a DueDate.\n2. Insert the Issued invoice without an IssuedAt.\n3. Insert the Issued invoice with a PaidAt.\n4. Insert the Paid invoice with a PaidAt.\n5. Insert the Cancelled invoice with a CancelledAt.', 'expected': '1. The first three inserts are refused.\n2. The last two inserts are accepted.'},
    "TC-152": {'title': 'The currency defaults to SGD', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S4 (lowest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Low', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.', 'test_data': 'Invoice row without CurrencyCode', 'steps': '1. Insert an invoice without a CurrencyCode.\n2. Read the saved row and the amounts on SCR-02.', 'expected': '1. The saved CurrencyCode is SGD.\n2. SCR-02 shows the amounts in SGD.'},
    "TC-153": {'title': 'A second open transaction for an invoice is refused by the database', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. INV-2026-000111 of S08 is PaymentPending and has one Pending transaction, PAY-20261020-000004 (CompletedAt empty), from the seed.', 'test_data': 'Invoice INV-2026-000111 with one open transaction', 'steps': '1. Insert a second transaction for the same invoice with CompletedAt empty.', 'expected': '1. The insert is refused by the unique index for one open transaction per invoice.'},
    "TC-154": {'title': 'A second Succeeded transaction for an invoice is refused', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. INV-2026-000119 of S13 is Paid and has one Succeeded transaction, PAY-20261008-000002, from the seed. The Failed transaction PAY-20261008-000001 does not count.', 'test_data': 'Invoice INV-2026-000119 with one Succeeded transaction', 'steps': '1. Insert a second transaction for the same invoice with the status Succeeded.', 'expected': '1. The insert is refused by the unique index for one successful transaction per invoice.'},
    "TC-155": {'title': 'An idempotency key is unique for a Parent and can repeat across Parents', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. Transaction PAY-20261008-000002 exists for the Parent IAM-PAR-S13 with the key seed-r9-r9-inv-0119-2 (seed).', 'test_data': 'Keys: seed-r9-r9-inv-0119-2 for IAM-PAR-S13 twice; seed-r9-r9-inv-0119-2 for IAM-PAR-S16', 'steps': '1. Insert a transaction for IAM-PAR-S13 with the key seed-r9-r9-inv-0119-2.\n2. Insert a transaction for IAM-PAR-S16 with the key seed-r9-r9-inv-0119-2.', 'expected': '1. The insert for IAM-PAR-S13 is refused.\n2. The insert for IAM-PAR-S16 is accepted.'},
    "TC-156": {'title': 'A FundingReference is unique and a split uses two different references', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. The seed has the finished split payment PAY-20260720-000003 of INV-2026-000121 (S16 Darren Ho).', 'test_data': 'Funding legs: FND-20260720-000003-1 (EA, ledger 8000056) and FND-20260720-000003-2 (online, sbx_pi_2026072000004)', 'steps': '1. Read the FundingReference of the EA leg and of the online leg.\n2. Insert a leg with the FundingReference of the EA leg.', 'expected': '1. The two legs have different FundingReferences.\n2. The EA reference is the one in the Function 1 ledger and the online reference is the one at the provider.\n3. The duplicate insert is refused.'},
    "TC-157": {'title': 'Wallet and provider fields depend on the leg method', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.', 'test_data': 'Leg rows: EA leg without WalletId; correct EA leg with WalletId; online leg with WalletId; online leg without ProviderCode; correct online leg with ProviderCode', 'steps': '1. Insert each leg row.', 'expected': '1. An EA leg without a WalletId is refused. An online leg with a WalletId is refused. An online leg without a ProviderCode is refused.\n2. A correct EA leg with a WalletId and a correct online leg with a ProviderCode are accepted.'},
    "TC-158": {'title': 'Ledger and provider IDs are stored when they must be and are unique', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. The seed has an EA leg Succeeded (R9-FND-0002, ledger 8000046), an EA leg Reversed (R9-FND-0007, debit 8000024, reversal 8000026) and an online leg Succeeded (R9-FND-0004, sbx_pi_2026072000004).', 'test_data': 'Legs: R9-FND-0002 (EA Succeeded); R9-FND-0007 (EA Reversed); R9-FND-0004 (online Succeeded)', 'steps': '1. Read EducationAccountTransactionId on the Succeeded EA leg.\n2. Read EducationAccountReversalTransactionId on the Reversed EA leg.\n3. Read ProviderTransactionId on the Succeeded online leg.\n4. Insert a leg that repeats one of these IDs.', 'expected': '1. The Succeeded EA leg has a ledger ID. The Reversed EA leg has a reversal ID. The Succeeded online leg has a ProviderTransactionId.\n2. The duplicate IDs are refused.'},
    "TC-159": {'title': 'Leg amounts add up to the transaction and the transaction equals the invoice Net', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. The seed has the Succeeded split payment PAY-20260720-000003 of INV-2026-000121 (S16 Darren Ho): EA 10.00 and online 11.26.', 'test_data': 'Transaction PAY-20260720-000003: EA 10.00 + online 11.26 = 21.26 = Net of INV-2026-000121', 'steps': '1. Read the Requested and Settled amounts of the invoice, the transaction and the two legs.', 'expected': '1. The leg Requested amounts are 10.00 and 11.26 and add up to the transaction Requested amount 21.26.\n2. The transaction Requested amount equals the invoice Net 21.26.\n3. For the Succeeded transaction Settled equals Requested.'},
    "TC-160": {'title': 'An amount other than the invoice Net cannot be requested', 'suite': 'Data rules and constraints', 'page': 'API: create payment', 'severity': 'S1 (highest)', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.\n2. INV-2026-000101 (27.25) of S01 Nur Aisyah is Issued.', 'test_data': 'Student: S01 Nur Aisyah (Meridian Secondary, Sec 3, class Sec 3 Excellence), Singapore Citizen, EA Active, balance 1,590.00 SGD\nInvoice: INV-2026-000101 (Miscellaneous fee, Term 4), Issued, Net 27.25 SGD, in the seed state after a reset\nRequested amount sent: 10.00\nIdempotency key: API-KEY-160', 'steps': '1. Send the create payment request with the amount 10.00.\n2. Look at the answer and the transactions.\n3. Look for a PartiallyPaid status or a PaidAmount in the invoice data.', 'expected': '1. No transaction is created with a Requested amount other than 27.25.\n2. The invoice has no PartiallyPaid status and no PaidAmount.\n3. The invoice is Paid only when a payment of the full 27.25 succeeds.'},
    "TC-161": {'title': 'Settled above Requested and a leg amount of zero are refused', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.', 'test_data': 'Transaction rows: Requested 50.00 with Settled 50.01; leg row with Requested 0.00', 'steps': '1. Insert the transaction with Settled 50.01.\n2. Insert the leg with Requested 0.00.', 'expected': '1. Both inserts are refused.'},
    "TC-162": {'title': 'CompletedAt is empty while processing and filled when the transaction is final', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. A split payment is in progress: the transaction is Pending, the EA leg is Succeeded, the online leg is Pending and the invoice is PaymentPending.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD', 'steps': '1. Read CompletedAt of the transaction and of the legs while the online leg is Pending.\n2. Finish the payment with the success outcome.\n3. Read CompletedAt again.', 'expected': '1. While processing, CompletedAt of the transaction is empty.\n2. After the success, CompletedAt of the transaction and of each leg is filled.'},
    "TC-164": {'title': 'System error while loading the invoice list shows a safe message', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05', 'preconditions': '1. PAR-S10 has a valid session and has chosen S10 on SCR-01.\n2. A Function 9 service is set to return an error for the invoice list.', 'test_data': 'Parent: PAR-S10\nStudent: S10', 'steps': '1. Open SCR-02 of S10 while the service returns an error.\n2. Look at the screen, the invoices, the transactions and the EA balance of S10.\n3. Set the service back to normal and use the try again action.', 'expected': '1. SCR-02 shows the Error state with the message "Something went wrong. Please try again later."\n2. The Parent can try again. No technical detail is shown.\n3. No data is changed: no invoice, transaction or EA balance of S10 changes.\n4. After the service works again, SCR-02 shows the invoices of S10.'},
    "TC-166": {'title': 'A second guardian pays an invoice of the shared child and the payment is recorded for that guardian', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-07 Payment confirmation', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S25-F, the second guardian of S25, is signed in. PAR-S25 is also linked to S25.\n2. S25 EA is Active with balance 730.00.\n3. INV-2026-000126 of S25 is Issued with Net 2.25 and has no transaction.', 'test_data': 'Parents: PAR-S25-F (pays), PAR-S25 (checks afterwards)\nStudent: S25 Nadia Karim (Bukit View Primary, P4, class P4 Kindness), Singapore Citizen, EA Active, balance 730.00 SGD\nInvoice: INV-2026-000126 (Miscellaneous fee, Term 4), Issued, Gross 27.25, FAS subsidy 25.00, Net 2.25 SGD, in the seed state after a reset\nMethod: EA\nIdempotency key: client generated', 'steps': '1. As PAR-S25-F choose S25, select INV-2026-000126, choose the EA method and confirm.\n2. Read SCR-07.\n3. Look at the transaction (which Parent started it), the EA leg, the invoice and the EA balance.\n4. Sign out, sign in as PAR-S25, open S25 and read the EA balance and the invoice.', 'expected': '1. SCR-07 shows success, a transaction reference, the time, the EA part 2.25 and the total 2.25.\n2. The transaction is Succeeded and records PAR-S25-F as the Parent who started it. The EA leg is Succeeded.\n3. The invoice is Paid. The EA balance of S25 is 727.75, debited once.\n4. PAR-S25 sees the EA balance 727.75 and cannot pay the invoice again.'},
    "TC-167": {'title': 'Status changes of a split payment that is returned are written to the audit log', 'suite': 'F9.4 and F9.5 Split payment', 'page': 'Audit log', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-03, ENV-R9-05', 'preconditions': '1. PAR-S02, linked to S02, started the payment from INV-2026-000103 in the seed state after a reset.\n2. S02 EA is Active with balance 20.00.\n3. A split payment of EA 20.00 and online 50.63 is confirmed. The EA leg is Succeeded, the online leg is Pending and the invoice is PaymentPending.', 'test_data': 'Student: S02 Aisha Rahman (Bukit View Primary, P3, class P3 Respect), Singapore Citizen, EA Active, balance 20.00 SGD\nInvoice: INV-2026-000103 (School Meal Fee, Nov), Issued, Net 70.63 SGD, in the seed state after a reset\nMethod: SPLIT, EA 20.00, online 50.63\nProvider outcome: failure\nSeed history on INV-2026-000103: Failed transaction PAY-20261019-000006 (EA 20.00 Reversed, online 50.63 Failed). Count only new transactions.', 'steps': '1. At the provider choose the failure outcome and return to the portal.\n2. Read the audit log entries of the transaction, the two legs and the invoice in time order.\n3. Read the EA balance of S02.', 'expected': '1. The entries show: transaction created Pending and invoice Issued to PaymentPending; EA leg Pending to Succeeded; online leg Pending to Failed; EA leg Succeeded to Reversed; transaction Pending to Failed; invoice PaymentPending to Issued.\n2. The EA leg is Reversed before the transaction is Failed, as Appendix A requires.\n3. Each entry has the actor, the action, the entity, the old and new value and a time.\n4. The EA balance of S02 is 20.00 again.'},
    "TC-168": {'title': 'Two invoices cannot share an invoice number', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S2', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.\n2. Invoice INV-2026-000101 exists.', 'test_data': 'Invoice rows: a new invoice with a new Id and the InvoiceNumber of INV-2026-000101; a new invoice with a new Id and a new InvoiceNumber\nBoth new invoices follow every other rule of BR-F9-12', 'steps': '1. Insert the new invoice with the InvoiceNumber of INV-2026-000101.\n2. Insert the new invoice with a new InvoiceNumber.\n3. Read INV-2026-000101.', 'expected': '1. The first insert is refused as a duplicate InvoiceNumber.\n2. The second insert is accepted.\n3. INV-2026-000101 is unchanged.'},
    "TC-169": {'title': 'The line number of an invoice line is above 0 and unique inside its invoice', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.\n2. Two test invoices, TST-A and TST-B, exist. Each new line has its own new StudentChargeId and follows every other rule of BR-F9-12.', 'test_data': 'Lines of TST-A: LineNumber 0; LineNumber -1; LineNumber 2 twice; LineNumber 1\nLine of TST-B: LineNumber 1', 'steps': '1. Insert a line with LineNumber 0 into TST-A.\n2. Insert a line with LineNumber -1 into TST-A.\n3. Insert a line with LineNumber 2 into TST-A, then a second line with LineNumber 2 into TST-A.\n4. Insert a line with LineNumber 1 into TST-A and a line with LineNumber 1 into TST-B.', 'expected': '1. The insert with LineNumber 0 is refused.\n2. The insert with LineNumber -1 is refused.\n3. The first line with LineNumber 2 is accepted. The second line with LineNumber 2 in the same invoice is refused.\n4. Both lines with LineNumber 1 are accepted because the number is unique only inside its invoice.'},
    "TC-171": {'title': 'The sequence number of a funding leg is above 0 and unique inside its transaction', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Approve', 'assumption': 'N/A', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.\n2. Two test transactions, TST-T1 and TST-T2, exist. Each new leg has its own FundingReference and follows every other rule of 4.2.', 'test_data': 'Legs of TST-T1: SequenceNumber 0; SequenceNumber -1; SequenceNumber 1 twice; SequenceNumber 2\nLeg of TST-T2: SequenceNumber 1', 'steps': '1. Insert a leg with SequenceNumber 0 into TST-T1.\n2. Insert a leg with SequenceNumber -1 into TST-T1.\n3. Insert a leg with SequenceNumber 1 into TST-T1, then a second leg with SequenceNumber 1 into TST-T1.\n4. Insert a leg with SequenceNumber 2 into TST-T1 and a leg with SequenceNumber 1 into TST-T2.', 'expected': '1. The insert with SequenceNumber 0 is refused.\n2. The insert with SequenceNumber -1 is refused.\n3. The first leg with SequenceNumber 1 is accepted. The second leg with SequenceNumber 1 in the same transaction is refused.\n4. Both inserts are accepted because the number is unique only inside its transaction.'},
    "TC-173": {'title': 'The FAS subsidy of each line is shown and Net is Gross minus subsidy, rounded half up', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-36: the seed carries the R4 FAS subsidy, BR-F9-08 says Sprint 1 shows subsidy 0. Run this case only when BA confirms that the subsidy is shown. TC-020 covers the Sprint 1 rule.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in.\n2. The seed is loaded as delivered (@ApplyFasSubsidy = 1, which is the opposite of BR-F9-08, open point O19).\n3. S10 Ethan Chua has INV-2026-000114 (Issued, two lines) and INV-2026-000115 and INV-2026-000116 (Issued).', 'test_data': 'Parent: PAR-S10\nStudent: S10 Ethan Chua (MOEFAS Tier 2, 50%)\nINV-2026-000114: line CH12 Miscellaneous fee Gross 36.33, Subsidy 25.00, Net 11.33; line CH14 Service charge Gross 10.90, Subsidy 0.00, Net 10.90; invoice Gross 47.23, Subsidy 25.00, Net 22.23\nINV-2026-000115 and INV-2026-000116: Gross 36.33, Subsidy 16.67, Net 19.66 each', 'steps': '1. On SCR-01 choose S10 Ethan Chua.\n2. Expand INV-2026-000114 and read Gross, Subsidy and Net of both lines.\n3. Read the Subsidy and the amount to pay of the invoice.\n4. Read the Subsidy and the amount to pay of INV-2026-000115 and INV-2026-000116.', 'expected': '1. Line CH12 shows Gross 36.33, Subsidy 25.00 and Net 11.33.\n2. Line CH14 (Service charge) shows Gross 10.90, Subsidy 0.00 and Net 10.90, because the service charge has no subsidy rate.\n3. INV-2026-000114 shows Subsidy 25.00 and an amount to pay of 22.23, equal to 11.33 + 10.90.\n4. INV-2026-000115 and INV-2026-000116 each show Subsidy 16.67 and an amount to pay of 19.66 (36.33 minus 16.67, rounded half up).\n5. The total owed of S10 is 36.33 + 22.23 + 19.66 + 19.66 = 97.88.'},
    "TC-174": {'title': 'An invoice with a 100% FAS subsidy still has the GST to pay and is payable by EA', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-36: the seed carries the R4 FAS subsidy, BR-F9-08 says Sprint 1 shows subsidy 0. The GST is not subsidised in the seed (Read me point 2 of R9_Seed_Data.xlsx).', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S25 is signed in.\n2. The seed is loaded as delivered (@ApplyFasSubsidy = 1, see ASM-R9-36).\n3. S25 Nadia Karim (MOEFAS Tier 1, 100% of the base amount) has an Active EA with balance 730.00 and the Issued invoices INV-2026-000126 and INV-2026-000127.', 'test_data': 'Parent: PAR-S25\nStudent: S25 Nadia Karim\nINV-2026-000126: Gross 27.25, Subsidy 25.00, Net 2.25\nINV-2026-000127: Gross 70.63, Subsidy 64.80, Net 5.83\nThe subsidy covers the base amount only, so the GST (2.25 and 5.83) stays to pay.\nEA balance 730.00', 'steps': '1. On SCR-01 choose S25 Nadia Karim and read the two invoices.\n2. Pay INV-2026-000126 by EA and read the receipt and the EA balance.\n3. Pay INV-2026-000127 by EA and read the EA balance.', 'expected': '1. INV-2026-000126 shows Net 2.25 and INV-2026-000127 shows Net 5.83. Neither shows 0.00, and the EA only option is available for both.\n2. INV-2026-000126 becomes Paid with an EA leg of 2.25. The EA balance falls from 730.00 to 727.75.\n3. INV-2026-000127 becomes Paid with an EA leg of 5.83. The EA balance falls to 721.92.\n4. Each payment has one transaction and one EA debit equal to the Net amount.'},
    "TC-175": {'title': 'A child aged 16 or older is listed with the invoice but the Pay button is not offered', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-38: the seed shows the invoice of a child aged 16 or older with no Pay button because of the R8 rule. FS 9 is silent.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S25 is signed in. X01 Hakim Karim (date of birth 22/10/2010, aged 16) is a child of PAR-S25.\n2. X01 has an EA with the status Due for closure (balance 2,025.00) and the Issued invoice INV-2026-000129 (27.25, due 30/10/2026).', 'test_data': 'Parent: PAR-S25\nStudent: X01 Hakim Karim, Sec 4 Harmony, Meridian Secondary, aged 16\nInvoice: INV-2026-000129, Net 27.25, Issued', 'steps': '1. On SCR-01 read the list of children of PAR-S25.\n2. Choose X01 Hakim Karim and read SCR-02.\n3. Look for the Pay button of INV-2026-000129.', 'expected': '1. SCR-01 lists S25 Nadia Karim, X01 Hakim Karim and X02 Sara Karim.\n2. SCR-02 of X01 shows INV-2026-000129 with the amount 27.25.\n3. No Pay button is offered for the invoice of a child aged 16 or older (R8 rule). FS 9 does not state this: open point O22 in the R9 validation rules.'},
    "TC-176": {'title': 'Children are listed in alphabetical order of name', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S4 (lowest)', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Low', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S25 is signed in.\n2. PAR-S25 is linked to S25 Nadia Karim, X01 Hakim Karim and X02 Sara Karim.', 'test_data': 'Parent: PAR-S25\nChildren in the seed order: S25 Nadia Karim, X01 Hakim Karim, X02 Sara Karim', 'steps': '1. Open SCR-01.\n2. Read the order of the child cards.', 'expected': '1. Three cards are shown.\n2. The order is X01 Hakim Karim, S25 Nadia Karim, X02 Sara Karim (A to Z by name), not the order of the seed.'},
    "TC-177": {'title': 'A double click on a child card opens the invoice list once', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in and is on SCR-01.\n2. S10 Ethan Chua and X03 Emma Chua are listed.', 'test_data': 'Parent: PAR-S10\nCard: S10 Ethan Chua', 'steps': '1. Double click the card of S10 Ethan Chua quickly.\n2. Press the browser Back button once.', 'expected': '1. SCR-02 of S10 opens once with the four invoices of S10.\n2. The browser history has one new entry: Back returns to SCR-01 in one step.\n3. No error is shown and no second list request is sent.'},
    "TC-178": {'title': 'The debt label counts Issued invoices only', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. The seed is loaded as delivered.\n2. PAR-S25 and PAR-S05 can sign in.', 'test_data': 'PAR-S25: S25 Nadia Karim (INV-2026-000126 and INV-2026-000127, Issued), X01 Hakim Karim (INV-2026-000129, Issued), X02 Sara Karim (no invoice)\nPAR-S05: S05 Chen Xin Yi (INV-2026-000106, PaymentPending only)', 'steps': '1. Sign in as PAR-S25 and read the label of each card.\n2. Sign in as PAR-S05 and read the label of the card of S05.', 'expected': '1. S25 and X01 show "Has outstanding invoices". X02 shows "No outstanding invoices".\n2. S05 shows "No outstanding invoices", because its only invoice is PaymentPending.'},
    "TC-179": {'title': 'A loading state is shown while the child list loads', 'suite': 'F9.1 Access and child list', 'page': 'SCR-01 Choose child', 'severity': 'S4 (lowest)', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Low', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 can sign in.\n2. The child list request can be slowed down by 3 seconds (browser developer tools).', 'test_data': 'Parent: PAR-S10\nDelay of the child list request: 3 seconds', 'steps': '1. Slow down the child list request.\n2. Sign in as PAR-S10 and watch SCR-01 until the list appears.', 'expected': '1. A loading indicator is shown while the request runs.\n2. No empty state ("You have no linked student") and no stale card is shown before the list arrives.\n3. After the delay two cards appear: S10 Ethan Chua and X03 Emma Chua.'},
    "TC-180": {'title': 'Malformed or hostile IDs in a request are refused without a server error', 'suite': 'F9.1 Access and child list', 'page': 'API: list invoices', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.\n2. INV-2026-000101 is Issued and the EA balance of S01 is 1,590.00.', 'test_data': "Student IDs: abc; a GUID with one extra character (37 characters); ' OR 1=1 --; <script>alert(1)</script>; a GUID followed by a null byte\nInvoice ID of 51 characters; transaction reference of 51 characters\nCalls: list invoices, invoice detail, create payment, payment status, receipt", 'steps': '1. Send each call with each malformed value in place of the real ID.\n2. Read the status code and the body of every answer.\n3. Look at the security log, the transactions and the balance of S01.', 'expected': '1. Every call is refused (400 or 403). No call answers 200 with data or a 5xx error.\n2. No body shows a stack trace, a SQL error or the value as HTML.\n3. A security log entry is written for each refusal.\n4. No transaction is created, INV-2026-000101 is still Issued and the balance of S01 is 1,590.00.'},
    "TC-181": {'title': 'The answer for an ID of another family is the same as for an ID that does not exist', 'suite': 'F9.1 Access and child list', 'page': 'API: invoice detail', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S01 has a valid session.\n2. S10 Ethan Chua exists and is not linked to PAR-S01.', 'test_data': 'Student of another family: S10, Id f063b14b-8ec5-507d-84ad-9a9d36a79c26\nStudent that does not exist: 00000000-0000-0000-0000-000000000001\nInvoice of another family: INV-2026-000114\nInvoice that does not exist: INV-2026-000999', 'steps': '1. Call list invoices for the S10 Id and for the unknown Id.\n2. Call invoice detail for INV-2026-000114 and for INV-2026-000999.\n3. Compare the status code and the body of each pair.', 'expected': '1. For each pair the status code and the body are the same (403 FORBIDDEN_CHILD).\n2. The answer does not show whether the ID exists.\n3. No data of S10 is returned.'},
    "TC-182": {'title': 'A line description with HTML is shown as text and is not executed', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S01 is signed in.\n2. Helper H-DESC has set the description of the line of INV-2026-000101 to the test text.', 'test_data': 'Student: S01 Nur Aisyah\nInvoice: INV-2026-000101\nDescription after H-DESC: <b>Fees</b><script>alert(1)</script>', 'steps': '1. On SCR-01 choose S01 Nur Aisyah.\n2. Expand INV-2026-000101 and read the description of the line.', 'expected': '1. The description is shown as the plain text <b>Fees</b><script>alert(1)</script>.\n2. No text is bold and no alert box opens: the HTML is encoded in the output.\n3. The line amounts are unchanged (27.25).'},
    "TC-183": {'title': 'A double click on Pay opens the payment method screen once', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S01 is signed in and is on SCR-02 of S01.\n2. INV-2026-000101 is Issued with no open transaction.', 'test_data': 'Student: S01 Nur Aisyah\nInvoice: INV-2026-000101 (27.25)', 'steps': '1. Double click Pay of INV-2026-000101 quickly.\n2. Look at the screen and at the transactions of the invoice.', 'expected': '1. SCR-04 opens once for INV-2026-000101.\n2. The browser history has one new entry.\n3. No transaction exists for the invoice and it is still Issued.'},
    "TC-184": {'title': 'The back to child list button works on the invoice list and on the empty state', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. The seed is loaded as delivered.\n2. PAR-S10 and PAR-S13 can sign in.', 'test_data': 'PAR-S10: S10 Ethan Chua (four Issued invoices)\nPAR-S13: S13 Amira Hassan (no Issued invoice, SCR-03)', 'steps': '1. Sign in as PAR-S10, open SCR-02 of S10 and click the back to child list button.\n2. Sign in as PAR-S13, open S13 (SCR-03) and click the same button.', 'expected': '1. The button is shown on SCR-02 and on SCR-03.\n2. Each click opens SCR-01 with the children of that Parent (S10 and X03; S13).\n3. No data changes.'},
    "TC-185": {'title': 'A loading state is shown while the invoice list loads', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S4 (lowest)', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Low', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S10 is signed in.\n2. The invoice list request can be slowed down by 3 seconds.', 'test_data': 'Student: S10 Ethan Chua\nDelay of the invoice list request: 3 seconds', 'steps': '1. Slow down the invoice list request.\n2. Choose S10 Ethan Chua and watch SCR-02 until the list appears.', 'expected': '1. A loading indicator is shown while the request runs.\n2. The message "There are no outstanding fees for this child." is not shown before the list arrives.\n3. After the delay the four invoices appear.'},
    "TC-186": {'title': 'A payment method is preselected for each state and Continue needs a method', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. The seed is loaded as delivered.\n2. PAR-S01, PAR-S02 and PAR-S07 can sign in.', 'test_data': 'S01: balance 1,590.00, INV-2026-000101 (27.25)\nS02: balance 20.00, INV-2026-000103 (70.63)\nS07: no EA, INV-2026-000109 (21.26)', 'steps': '1. Open SCR-04 for each invoice and read the selected method and the Continue button.\n2. If a state has no selected method, read the Continue button.', 'expected': '1. S01: the EA is suggested and selected. Nothing is debited.\n2. S02: Split is selected and the EA only option is disabled with its reason.\n3. S07: Online is the only method and is selected.\n4. Where no method is selected, Continue is disabled until one is chosen.'},
    "TC-187": {'title': 'The EA part rejects values that are not numbers', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 of INV-2026-000103 with Split selected.\n2. S02 EA balance is 20.00.', 'test_data': 'Values: empty; abc; S$20; -5; 1e2; 20,5 (comma as decimal); only spaces', 'steps': '1. Enter each value in the EA part and click Continue.\n2. After each value read the message, the screen and the online part.', 'expected': '1. Each value is refused with "The two amounts must be more than zero and add up to the total." and the EA part field is marked.\n2. The screen stays on SCR-04. The online part is not set to a wrong number.\n3. No transaction is created and the balance of S02 is 20.00.'},
    "TC-188": {'title': 'The EA part follows the length, decimal and space rules', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 of INV-2026-000103 with Split selected.\n2. S02 EA balance is 20.00.', 'test_data': 'Refused: 20.001; 1234567890.12 (13 characters); 2 0 (space inside)\nAccepted: 20; 20.00; 10.5; "  20.00  " (spaces around)', 'steps': '1. Enter each refused value and click Continue.\n2. Enter each accepted value and read the online part.', 'expected': '1. 20.001, 1234567890.12 and "2 0" are refused with SPLIT_AMOUNT_INVALID and nothing changes.\n2. 20 and 20.00 give an online part of 50.63. 10.5 gives 60.13.\n3. "  20.00  " is trimmed and accepted as 20.00 with an online part of 50.63.'},
    "TC-189": {'title': 'The EA part treats script, SQL and special characters as text', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S1 (highest)', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Critical', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 of INV-2026-000103 with Split selected.', 'test_data': 'Values: \' OR 1=1 --; <script>alert(1)</script>; {"a":1}; ${7*7}; ../../etc/passwd; a null byte; an emoji', 'steps': '1. Enter each value in the EA part and click Continue.\n2. Look at the screen, the message and the network answer.', 'expected': '1. Each value is refused with SPLIT_AMOUNT_INVALID because it is not a number.\n2. Nothing is executed: no alert box, no 49 for ${7*7}, no file content.\n3. The value is not shown as HTML. No 5xx error occurs and no data changes.'},
    "TC-190": {'title': 'The EA part and the online part go back to the default when the method or the invoice changes', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 of INV-2026-000103.\n2. S02 EA balance is 20.00.', 'test_data': 'Invoice: INV-2026-000103 (70.63), default EA part 20.00, online part 50.63\nLowered EA part: 10.00 (online part 60.63)', 'steps': '1. Select Split and lower the EA part to 10.00.\n2. Select Online, then select Split again.\n3. Lower the EA part to 10.00 again, go back to SCR-02 and open INV-2026-000103 again.', 'expected': '1. After step 1 the online part is 60.63.\n2. After step 2 the EA part is 20.00 and the online part is 50.63 again.\n3. After step 3 the EA part is 20.00 and the online part is 50.63 again.'},
    "TC-191": {'title': 'A failed check on Continue keeps the screen and changes no data, and a double click opens the next screen once', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S02 is signed in and is on SCR-04 of INV-2026-000103 with Split selected.\n2. S02 EA balance is 20.00.', 'test_data': 'Invalid EA part: 25.00 (above the balance)\nValid EA part: 20.00', 'steps': '1. Enter 25.00 and click Continue.\n2. Check the transactions of INV-2026-000103, the invoice status and the balance.\n3. Enter 20.00 and double click Continue quickly.', 'expected': '1. EA_INSUFFICIENT_BALANCE is shown: "Your Education Account balance is not enough for this amount. You can pay the rest online." The screen stays on SCR-04.\n2. No new transaction exists (only the seeded PAY-20261019-000006), the invoice is Issued and the balance is 20.00.\n3. SCR-05 opens once with EA 20.00 and online 50.63. Still no new transaction.'},
    "TC-192": {'title': 'Back on the payment method screen returns to the invoice list and changes nothing', 'suite': 'F9.3 Payment method and eligibility', 'page': 'SCR-04 Choose payment method', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S01 is signed in and is on SCR-04 of INV-2026-000101 with the EA method selected.', 'test_data': 'Student: S01 Nur Aisyah, balance 1,590.00\nInvoice: INV-2026-000101 (27.25)', 'steps': '1. Double click Back quickly.\n2. Read SCR-02.\n3. Check the transactions and the balance.', 'expected': '1. SCR-02 opens once (the destination is a QA proposal, FS does not state it).\n2. INV-2026-000101 is still Issued and listed.\n3. No transaction exists and the balance is 1,590.00.'},
    "TC-193": {'title': 'Cancel on the review screen leaves without paying and is disabled after Confirm', 'suite': 'F9.4 Pay with Education Account', 'page': 'SCR-05 Review and confirm', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S01 and PAR-S04 can sign in.\n2. INV-2026-000101 (S01) and INV-2026-000105 (S04) are Issued.', 'test_data': 'Part 1: PAR-S01, INV-2026-000101 (27.25), EA, balance 1,590.00\nPart 2: PAR-S04, INV-2026-000105 (21.26), EA, balance 975.00', 'steps': '1. As PAR-S01 open SCR-05 and click Cancel.\n2. Check the transactions, the invoice and the balance.\n3. As PAR-S04 open SCR-05, click Confirm and try to click Cancel while the screen shows Processing.', 'expected': '1. Cancel opens SCR-04 (QA proposal, FS does not state it). No transaction is created.\n2. INV-2026-000101 is still Issued and the balance of S01 is 1,590.00.\n3. After Confirm the Cancel button is disabled. One transaction exists for INV-2026-000105.'},
    "TC-194": {'title': 'An idempotency key with characters that are not allowed is refused and not corrected', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'API: create payment', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S04 has a valid session.\n2. INV-2026-000105 is Issued and the S04 EA balance is 975.00.', 'test_data': 'Refused keys: "key 1" (space inside); key\'1; key;1; <b>k</b>; {"k":1}; a key with the control character U+0001; a key with an emoji; " abc" (space before); "abc " (space after)\nAccepted keys: a UUID of 36 characters; a-b_c9', 'steps': '1. Send the create payment request (EA, INV-2026-000105) with each refused key.\n2. Check the transactions and the balance.\n3. Send the request with the UUID key.', 'expected': '1. Each refused key gets 400. The key is not trimmed or changed in silence.\n2. No transaction exists after step 1 and the balance is 975.00.\n3. The UUID key is accepted: one transaction is created, INV-2026-000105 is Paid and the balance is 953.74.'},
    "TC-195": {'title': 'The same key with different content is refused', 'suite': 'F9.4 and F9.5 Idempotency and concurrency', 'page': 'API: create payment', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S06 has a valid session.\n2. S06 has INV-2026-000107 (21.26) and INV-2026-000108 (70.63), both Issued, and EA balance 405.00.', 'test_data': 'Key K: any valid key\nRequest 1: EA, INV-2026-000107, key K\nRequest 2: EA, INV-2026-000108, key K\nRequest 3: ONLINE, INV-2026-000107, key K', 'steps': '1. Send request 1.\n2. Send request 1 again with the same key.\n3. Send request 2.\n4. Send request 3.\n5. Check the transactions and the balance.', 'expected': '1. Request 1 pays INV-2026-000107 by EA: one transaction, balance 383.74.\n2. The repeat returns the first result and debits nothing more.\n3. Requests 2 and 3 are refused with a conflict code (QA proposal) and create no transaction.\n4. INV-2026-000108 is still Issued. One transaction exists for S06 and the balance is 383.74.'},
    "TC-196": {'title': 'The waiting screen shows only Pending or ReconciliationRequired, the leg statuses and the reference', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-06 Pending', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. The seed has PAY-20261020-000004 (INV-2026-000111, Pending) and PAY-20261021-000005 (INV-2026-000106, ReconciliationRequired).\n2. PAR-S08 and PAR-S05 can sign in.', 'test_data': 'S08 Farhan Ismail: PAY-20261020-000004, online leg 27.25 Pending\nS05 Chen Xin Yi: PAY-20261021-000005, EA leg 27.25 ReconciliationRequired', 'steps': '1. As PAR-S08 open the waiting screen of INV-2026-000111.\n2. As PAR-S05 open the waiting screen of INV-2026-000106.\n3. As PAR-S05 try to open the failure screen of PAY-20261021-000005.', 'expected': '1. S08: the transaction status is Pending, the online leg 27.25 is Pending and the reference PAY-20261020-000004 is shown (PAY-YYYYMMDD-XXXXXX, at most 50 characters).\n2. S05: the status is ReconciliationRequired, the EA leg 27.25 is ReconciliationRequired, the screen says the payment is being verified and does not say it failed.\n3. The failure screen is not shown for this transaction: the Parent stays on the waiting screen.'},
    "TC-197": {'title': 'Refresh status only reads the status and is disabled for a few seconds after a click', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-06 Pending', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-05', 'preconditions': '1. PAR-S08 is signed in and is on the waiting screen of INV-2026-000111 (Pending).', 'test_data': 'Transaction: PAY-20261020-000004, online leg 27.25 Pending', 'steps': '1. Click Refresh status.\n2. Look at the button right after the click.\n3. Double click Refresh status quickly.\n4. Check the transactions, the provider calls and the EA balance.', 'expected': '1. The screen stays on the waiting screen while the status is Pending.\n2. The button is disabled for a few seconds after a click (QA proposal).\n3. A double click is harmless: one request is sent.\n4. No new transaction, no new charge at the provider and no EA debit: the balance of S08 is 1,370.00.'},
    "TC-198": {'title': 'Back to the fee list after a payment shows the empty state when no fee is left', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-07 Payment confirmation', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03', 'preconditions': '1. PAR-S01 is signed in.\n2. INV-2026-000101 (27.25) is the only Issued invoice of S01.', 'test_data': 'Student: S01 Nur Aisyah, balance 1,590.00\nInvoice: INV-2026-000101 (27.25)', 'steps': '1. Pay INV-2026-000101 by EA and wait for SCR-07.\n2. Click the back to fee list button.', 'expected': '1. SCR-07 shows the payment as Succeeded and the invoice as Paid.\n2. The button opens SCR-02: INV-2026-000101 is not listed. S01 has no more Issued invoice, so SCR-03 is shown with a link back to SCR-01.\n3. No data changes by the click.'},
    "TC-199": {'title': 'The receipt button exists only for a Succeeded payment and the file is named receipt_reference.pdf', 'suite': 'F9.7 Result, receipt and retry', 'page': 'SCR-07 Payment confirmation', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-03', 'preconditions': '1. The seed has PAY-20261008-000002 (Succeeded) and PAY-20261008-000001 (Failed) of INV-2026-000119 and PAY-20261020-000004 (Pending) of INV-2026-000111.\n2. PAR-S13 and PAR-S08 can sign in.', 'test_data': 'PAR-S13: PAY-20261008-000002 (EA 21.26 Succeeded), PAY-20261008-000001 (EA 21.26 Failed)\nPAR-S08: PAY-20261020-000004 (online 27.25 Pending)', 'steps': '1. As PAR-S13 open the success screen of PAY-20261008-000002 and download the receipt. Read the file name.\n2. Request the receipt of PAY-20261008-000001 for S13.\n3. As PAR-S08 open the waiting screen of PAY-20261020-000004 and look for a receipt button. Request its receipt.', 'expected': '1. The receipt button is shown and the file is named receipt_PAY-20261008-000002.pdf.\n2. The receipt of the Failed transaction is refused. No receipt button is shown on the failure screen.\n3. No receipt button is shown on the waiting screen and the receipt request of the Pending transaction is refused.'},
    "TC-200": {'title': 'Amounts and dates follow one format on every screen', 'suite': 'F9.2 Outstanding invoices and EA balance', 'page': 'SCR-02 Outstanding fees', 'severity': 'S4 (lowest)', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Low', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01', 'preconditions': '1. PAR-S01 and PAR-S10 can sign in.\n2. The seed is loaded as delivered.', 'test_data': 'S01 balance 1,590.00; S10 balance 3,183.50\nINV-2026-000101 due 30/10/2026; INV-2026-000113 due 31/07/2026\nPAY-20261008-000002 paid at 08/10/2026 10:12 SGT', 'steps': '1. Open SCR-02 of S01 and of S10 and read the balance and the due dates.\n2. As PAR-S13 open the success screen of PAY-20261008-000002 and read the paid at time.', 'expected': '1. Balances are shown as 1,590.00 and 3,183.50: thousand separator and two decimals.\n2. Due dates are shown as 30/10/2026 and 31/07/2026 (DD/MM/YYYY).\n3. The paid at time is shown as 08/10/2026 10:12 (24 hour, SGT).'},
    "TC-201": {'title': 'A request with the wrong number or order of legs, or a wrong method, is refused', 'suite': 'F9.3 Payment method and eligibility', 'page': 'API: create payment', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-05, ENV-R9-06', 'preconditions': '1. PAR-S04 has a valid session.\n2. INV-2026-000105 (21.26) is Issued and the S04 EA balance is 975.00.', 'test_data': 'Requests: EA with two legs; ONLINE with two legs; SPLIT with one leg; SPLIT with the online leg first; a leg with Method 0; a leg with Method 3', 'steps': '1. Send each request with a new key.\n2. Check the transactions, the invoice and the balance.', 'expected': '1. Every request is refused and creates no transaction and no leg.\n2. INV-2026-000105 is still Issued and the balance of S04 is 975.00.'},
    "TC-202": {'title': 'A valid callback that matches no leg is ignored and a callback with another amount needs reconciliation', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Webhook endpoint', 'severity': 'S2', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'High', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. PAR-S07 has started an online payment of INV-2026-000109: the online leg of 21.26 is Pending.\n2. QA can send a callback with a valid signature (provider simulator).', 'test_data': 'Callback A: valid signature, FundingReference that does not exist\nCallback B: valid signature, FundingReference of the online leg, amount 20.00 instead of 21.26', 'steps': '1. Send callback A.\n2. Check the receipt, the legs and the invoice.\n3. Send callback B.\n4. Check the leg and the invoice.', 'expected': '1. Callback A is stored as a receipt with the status Ignored. No leg or invoice changes.\n2. After callback B the online leg is ReconciliationRequired (QA proposal).\n3. INV-2026-000109 is not Paid.'},
    "TC-203": {'title': 'The callback text fields accept their maximum length and refuse one more character', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Webhook endpoint', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. QA can send a callback with a valid signature (provider simulator) for a Pending online leg.', 'test_data': 'Fields and limits: ProviderCode 40; ProviderEventId 128; ProviderTransactionId 128; FundingReference 50; EventType 50\nTried: the limit and the limit plus 1 for each field', 'steps': '1. For each field send a callback with a value at the limit.\n2. For each field send a callback with a value of limit plus 1.\n3. Check the receipts and the legs.', 'expected': '1. A value at the limit is accepted and stored in full.\n2. A value of limit plus 1 is refused and no receipt is stored.\n3. No leg or invoice changes by a refused callback.'},
    "TC-204": {'title': 'The stored error text of a failed callback is cleaned and at most 500 characters', 'suite': 'F9.6 Webhook and reconciliation', 'page': 'Webhook endpoint', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-01, ENV-R9-02, ENV-R9-04, ENV-R9-05', 'preconditions': '1. QA can make the processing of a valid callback fail (way agreed with Dev, ENV-R9-05).\n2. An online leg is Pending.', 'test_data': 'Callback: valid signature, processing made to fail with a long internal error', 'steps': '1. Send the callback.\n2. Read the receipt status and the stored error message.\n3. Read the leg status.', 'expected': '1. The receipt status is Failed.\n2. The error message has at most 500 characters and shows no stack trace, SQL text, file path or card data.\n3. The leg stays Pending and the reconciliation job can pick it up.'},
    "TC-205": {'title': 'An invoice number can have 50 characters and not 51', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.\n2. One test student of S16 can be used.', 'test_data': 'InvoiceNumber of 50 characters: INV-2026- followed by 41 letters X\nInvoiceNumber of 51 characters: the same with 42 letters X', 'steps': '1. Insert an invoice with the 50 character number.\n2. Insert an invoice with the 51 character number.\n3. Open the first invoice on SCR-02.', 'expected': '1. The insert with 50 characters is accepted.\n2. The insert with 51 characters is refused.\n3. The invoice number of 50 characters is shown on one line.'},
    "TC-206": {'title': 'A transaction reference is unique and the transaction status accepts only 1 to 5', 'suite': 'Data rules and constraints', 'page': 'Database', 'severity': 'S3', 'review': 'Draft', 'assumption': 'ASM-R9-39: the rule checked here is a QA proposal of the R9 validation rules that BA will add to FS 9. Until BA confirms it, the case is Draft.', 'priority': 'Medium', 'env': 'SIT\nChrome (latest)\nBuild: to be recorded at execution\nNeeds: ENV-R9-05', 'preconditions': '1. QA can write test rows in SIT.\n2. Two test invoices exist.', 'test_data': 'TransactionReference: PAY-20261025-000901 used twice\nStatus values tried: 0, 1, 2, 3, 4, 5, 6', 'steps': '1. Insert a transaction with the reference PAY-20261025-000901 for the first invoice.\n2. Insert a second transaction with the same reference for the second invoice.\n3. Insert transactions with Status 0, 1 to 5 and 6.', 'expected': '1. The first insert is accepted.\n2. The second insert is refused because the reference is not unique.\n3. Status 1 to 5 are accepted and Status 0 and 6 are refused.'},
}
